import { updateAnnotationReferences } from "./update";
import { detectStaleAnnotations } from "./detect";

/**
 * Batch update annotations and verify references
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-BATCH - Perform batch updates
 * @req REQ-MAINT-VERIFY - Verify annotation references
 * @param codebasePath Absolute path to the workspace root where annotations will be updated.
 * @param mappings Array of mapping objects describing path changes, each containing an oldPath and newPath.
 * @returns Total number of updated @story annotations across all mappings.
 */
export function batchUpdateAnnotations(
  codebasePath: string,
  mappings: { oldPath: string; newPath: string }[],
): number {
  let totalUpdated = 0;
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md // @req REQ-MAINT-BATCH - Perform batch updates
  for (const { oldPath, newPath } of mappings) {
    totalUpdated += updateAnnotationReferences(codebasePath, oldPath, newPath);
  }
  return totalUpdated;
}

/**
 * Verify annotation references in codebase after maintenance operations
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-VERIFY - Verify annotation references
 * @param codebasePath Absolute path to the workspace root whose annotations should be verified.
 * @returns Boolean indicating whether there are no stale annotations remaining (true if clean, false if any remain).
 */
export function verifyAnnotations(codebasePath: string): boolean {
  const staleAnnotations = detectStaleAnnotations(codebasePath);
  return staleAnnotations.length === 0;
}

#!/usr/bin/env node

import {
  EXIT_OK,
  EXIT_USAGE,
  handleDetect,
  handleVerify,
  handleReport,
  handleUpdate,
} from "./commands";
import { normalizeCliArgs, NormalizedCliArgs } from "./flags";

/**
 * Maintenance CLI entry point.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-DETECT - CLI support for detection of stale annotations
 * @req REQ-MAINT-VERIFY - CLI support for verification of annotations
 * @req REQ-MAINT-REPORT - CLI support for human-readable reports
 * @req REQ-MAINT-UPDATE - CLI support for updating annotation references
 * @req REQ-MAINT-BATCH - CLI support for batch maintenance operations
 * @req REQ-MAINT-SAFE - Provide clear exit codes and avoid unsafe defaults
 */
export function runMaintenanceCli(rawArgv: string[]): number {
  const initialNormalized: NormalizedCliArgs = normalizeCliArgs(rawArgv);
  const { subcommand: command } = initialNormalized;

  if (!command || command === "-h" || command === "--help") {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Branch to show usage when no command or help flag is provided; handle help requests safely and provide discoverable usage output
    printHelp();
    return EXIT_OK;
  }

  // Re-use the normalized arguments object for handlers so that they
  // receive the subcommand name and its raw argument vector unchanged.
  const normalized: NormalizedCliArgs = initialNormalized;

  try {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Catch unexpected errors and surface concise diagnostics without crashing
    switch (command) {
      case "detect":
        // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT - Branch to dispatch to detection handler when 'detect' is requested; dispatch to detection handler
        return handleDetect(normalized);
      case "verify":
        // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-VERIFY - Branch to dispatch to verification handler when 'verify' is requested; dispatch to verification handler
        return handleVerify(normalized);
      case "report":
        // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-REPORT - Branch to dispatch to reporting handler when 'report' is requested; dispatch to reporting handler
        return handleReport(normalized);
      case "update": {
        // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-UPDATE - Branch to dispatch to update handler when 'update' is requested; dispatch to update handler
        const result = handleUpdate(normalized);
        if (result === EXIT_USAGE) {
          // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Print help on usage errors from update; help branch for update usage errors
          printHelp();
        }
        return result;
      }
      default:
        // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Branch for unknown commands to emit diagnostics and safe usage guidance; handle unknown commands safely with diagnostics
        console.error(`Unknown command: ${command}`);
        printHelp();
        return EXIT_USAGE;
    }
  } catch (error: unknown) {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Catch-all error branch to prevent crashes and provide concise diagnostics; catch unexpected errors and surface concise diagnostics without crashing
    const message =
      error instanceof Error
        ? error.message
        : "Unknown error in maintenance CLI";
    console.error(`traceability-maint failed: ${message}`);
    return EXIT_USAGE;
  }
}

/**
 * Print CLI usage help for the maintenance tools.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide discoverable CLI usage information
 */
function printHelp(): void {
  // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Help branch ensures users can discover maintenance CLI usage safely; provide discoverable CLI usage information
  console.log(`traceability-maint - Traceability annotation maintenance tools

Usage:
  traceability-maint <command> [options]

Commands:
  detect   Detect stale @story annotations
  verify   Verify that traceability annotations are valid
  report   Generate a maintenance report
  update   Update @story annotation references

Options:
  --root <dir>        Workspace root to scan (defaults to current directory)
  --json              Output JSON where supported
  --format <text|json>  Output format for 'report' (default: text)
  --from <oldPath>    Old story path for 'update'
  --to <newPath>      New story path for 'update'
  --dry-run           Plan changes for 'update' without modifying files
  -h, --help          Show this help message
`);
}

if (require.main === module) {
  process.exit(runMaintenanceCli(process.argv));
}

/**
 * Subcommand handlers for the traceability-maint CLI.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-DETECT - CLI support for detection of stale annotations
 * @req REQ-MAINT-VERIFY - CLI support for verification of annotations
 * @req REQ-MAINT-REPORT - CLI support for human-readable reports
 * @req REQ-MAINT-UPDATE - CLI support for updating annotation references
 * @req REQ-MAINT-SAFE - Provide clear exit codes and avoid unsafe defaults
 */
import { detectStaleAnnotations } from "./detect";
import { verifyAnnotations } from "./batch";
import { updateAnnotationReferences } from "./update";
import { generateMaintenanceReport } from "./report";
import { parseFlags, NormalizedCliArgs } from "./flags";

export const EXIT_OK = 0;
export const EXIT_STALE = 1;
export const EXIT_USAGE = 2;

/**
 * Handle the `detect` subcommand for stale @story annotations.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-DETECT - CLI surface for detection of stale annotations
 * @req REQ-MAINT-SAFE - Return specific exit codes for stale vs clean states
 */
export function handleDetect(normalized: NormalizedCliArgs): number {
  const flags = parseFlags(normalized);
  const root = flags.root;
  const stale = detectStaleAnnotations(root);

  if (flags.json) {
    // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
    // @req REQ-MAINT-REPORT - JSON-friendly output for tooling integration
    console.log(JSON.stringify({ root, stale }));
  } else if (stale.length === 0) {
    console.log("No stale @story annotations found.");
  } else {
    stale.forEach((story) => {
      console.log(story);
    });
    console.log(
      `Found ${stale.length} stale @story annotation${
        stale.length === 1 ? "" : "s"
      }.
Run 'traceability-maint report' for a structured summary.`,
    );
  }

  return stale.length === 0 ? EXIT_OK : EXIT_STALE;
}

/**
 * Handle the `verify` subcommand to validate traceability annotations.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-VERIFY - CLI surface for verification of annotations
 * @req REQ-MAINT-SAFE - Return distinct exit codes for verification failures
 */
export function handleVerify(normalized: NormalizedCliArgs): number {
  const flags = parseFlags(normalized);
  const root = flags.root;
  const valid = verifyAnnotations(root);

  if (valid) {
    console.log(`All traceability annotations under ${root} are valid.`);
    return EXIT_OK;
  }

  console.log(
    `Stale or invalid traceability annotations detected under ${root}.\nRun 'traceability-maint detect' or 'traceability-maint report' for details.`,
  );
  return EXIT_STALE;
}

/**
 * Handle the `report` subcommand to generate a maintenance report.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-REPORT - CLI surface for human-readable maintenance reports
 * @req REQ-MAINT-SAFE - Support machine-readable formats for safe automation
 */
export function handleReport(normalized: NormalizedCliArgs): number {
  const flags = parseFlags(normalized);
  const root = flags.root;
  const format = flags.format ?? "text";

  const report = generateMaintenanceReport(root);

  if (format === "json") {
    console.log(JSON.stringify({ root, report }));
  } else if (!report) {
    console.log("No stale @story annotations found. Nothing to report.");
  } else {
    console.log(`# Traceability Maintenance Report for ${root}`);
    console.log("");
    console.log("Stale story references:");
    console.log(report);
  }

  return EXIT_OK;
}

/**
 * Handle the `update` subcommand to rewrite @story annotation references.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-UPDATE - CLI surface for updating annotation references
 * @req REQ-MAINT-SAFE - Provide dry-run mode and explicit parameter checks
 */
export function handleUpdate(normalized: NormalizedCliArgs): number {
  const flags = parseFlags(normalized);
  const root = flags.root;

  if (!flags.from || !flags.to) {
    console.error("'update' requires --from <oldPath> and --to <newPath>.");
    return EXIT_USAGE;
  }

  const from = flags.from;
  const to = flags.to;

  if (flags.dryRun) {
    // For now, we cannot get a per-file diff without changing the maintenance API.
    // We conservatively reuse generateMaintenanceReport to indicate potential impact.
    const beforeReport = generateMaintenanceReport(root);
    const potentialChanges = beforeReport ? beforeReport.split("\n").length : 0;
    const summary = {
      root,
      from,
      to,
      estimatedStaleCount: potentialChanges,
    };

    if (flags.json) {
      console.log(JSON.stringify({ mode: "dry-run", ...summary }));
    } else {
      console.log("Dry run: no files were modified.");
      console.log(
        `Would update @story annotations from '${from}' to '${to}' under ${root}.`,
      );
      console.log(
        `Estimated stale annotations before update: ${summary.estimatedStaleCount}.`,
      );
    }

    return EXIT_OK;
  }

  const count = updateAnnotationReferences(root, from, to);

  if (flags.json) {
    console.log(JSON.stringify({ root, from, to, updated: count }));
  } else {
    console.log(
      `Updated ${count} @story annotation${count === 1 ? "" : "s"} from '${from}' to '${to}' under ${root}.`,
    );
  }

  return EXIT_OK;
}

import * as fs from "fs";
import * as path from "path";
import { getAllFiles } from "./utils";
import {
  isUnsafeStoryPath,
  enforceProjectBoundary,
} from "../utils/storyReferenceUtils";
import type { ProjectBoundaryCheckResult } from "../utils/storyReferenceUtils";

/**
 * Detect stale annotation references that point to moved or deleted story files
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-DETECT - Detect stale annotation references
 * @param codebasePath Path to the codebase root, treated as a workspace root and resolved against process.cwd().
 * @returns A de-duplicated array of stale @story paths (as strings) whose resolved targets no longer exist on disk.
 */
export function detectStaleAnnotations(codebasePath: string): string[] {
  const cwd = process.cwd();
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Treat codebasePath as a workspace root resolved from process.cwd()
  const workspaceRoot = path.resolve(cwd, codebasePath);

  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Return empty result if workspaceRoot does not exist or is not a directory
  if (
    !fs.existsSync(workspaceRoot) ||
    !fs.statSync(workspaceRoot).isDirectory()
  ) {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    return [];
  }

  const stale = new Set<string>();

  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Iterate over all files in the isolated workspace root
  const files = getAllFiles(workspaceRoot);
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Loop over each workspace file to inspect its @story annotations
  for (const file of files) {
    processFileForStaleAnnotations(file, workspaceRoot, cwd, stale);
  }

  return Array.from(stale);
}

/**
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-DETECT - Process individual files to detect stale @story annotations
 */
function processFileForStaleAnnotations(
  file: string,
  workspaceRoot: string,
  cwd: string,
  stale: Set<string>,
): void {
  let content: string;
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Handle file read errors gracefully
  try {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    content = fs.readFileSync(file, "utf8");
  } catch {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Swallow file read failures without aborting detection
    return;
  }

  const regex = /@story\s+([^\s]+)/g;
  let match: RegExpExecArray | null;
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Iterate over regex matches for @story annotations
  while ((match = regex.exec(content)) !== null) {
    handleStoryMatch(match[1], workspaceRoot, cwd, stale);
  }
}

/**
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-DETECT REQ-SECURITY-VALIDATION - Handle individual @story matches within a file
 */
function handleStoryMatch(
  storyPath: string,
  workspaceRoot: string,
  cwd: string,
  stale: Set<string>,
): void {
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT REQ-SECURITY-VALIDATION - Skip traversal/absolute-unsafe or invalid-extension story paths before any filesystem or boundary checks
  if (isUnsafeStoryPath(storyPath)) {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    return;
  }

  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Compute project and codebase candidates relative to cwd and workspaceRoot
  const storyProjectCandidate = path.resolve(cwd, storyPath);
  const storyCodebaseCandidate = path.resolve(workspaceRoot, storyPath);

  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Enforce workspaceRoot as the project boundary for resolved story paths
  const inProjectCandidates = getInProjectCandidates(
    storyProjectCandidate,
    storyCodebaseCandidate,
    workspaceRoot,
  );

  // If both candidates are out-of-project, do not mark as stale and skip FS checks
  if (inProjectCandidates.length === 0) {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT - No in-project candidates means nothing to check or mark stale
    return;
  }

  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Only check existence for in-project candidates
  const anyExists = anyInProjectCandidateExists(inProjectCandidates);

  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-DETECT - Mark story as stale if any in-project candidate exists conceptually but none exist on disk
  if (!anyExists) {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    stale.add(storyPath);
  }
}

/**
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-DETECT - Enforce project boundary and return in-project candidates
 */
function getInProjectCandidates(
  storyProjectCandidate: string,
  storyCodebaseCandidate: string,
  workspaceRoot: string,
): string[] {
  let projectBoundary: ProjectBoundaryCheckResult;
  let codebaseBoundary: ProjectBoundaryCheckResult;

  try {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    projectBoundary = enforceProjectBoundary(
      storyProjectCandidate,
      workspaceRoot,
    );
  } catch {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Treat boundary enforcement failures as out-of-project
    projectBoundary = {
      isWithinProject: false,
      candidate: storyProjectCandidate,
    };
  }

  try {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    codebaseBoundary = enforceProjectBoundary(
      storyCodebaseCandidate,
      workspaceRoot,
    );
  } catch {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Treat boundary enforcement failures as out-of-project
    codebaseBoundary = {
      isWithinProject: false,
      candidate: storyCodebaseCandidate,
    };
  }

  const inProjectCandidates: string[] = [];
  if (projectBoundary.isWithinProject) {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT - Collect project-relative in-project candidate
    inProjectCandidates.push(projectBoundary.candidate);
  }
  if (codebaseBoundary.isWithinProject) {
    // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT - Collect workspace-root-relative in-project candidate
    inProjectCandidates.push(codebaseBoundary.candidate);
  }

  return inProjectCandidates;
}

/**
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-DETECT - Check on-disk existence of in-project candidates
 */
function anyInProjectCandidateExists(inProjectCandidates: string[]): boolean {
  return inProjectCandidates.some(
    /**
     * @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-DETECT REQ-MAINT-SAFE
     */
    (p) => {
      const exists = fs.existsSync(p);
      if (!exists) {
        // @supports docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md REQ-MAINT-SAFE - Safely handle non-existent candidate without throwing
      }
      return exists;
    },
  );
}

/**
 * Flag parsing and normalization logic for the traceability-maint CLI.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
import path from "path";

/**
 * Parsed representation of raw CLI input (argv) for the maintenance tools.
 *
 * Separates Node/V8 internals from the actual subcommand and its arguments.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
export interface ParsedCliInput {
  /**
   * The raw argv as passed to the Node.js process (e.g., process.argv).
   */
  readonly argv: string[];

  /**
   * The Node.js executable path (argv[0]).
   */
  readonly node: string;

  /**
   * The executed script path (argv[1]).
   */
  readonly script: string;

  /**
   * The maintenance subcommand being invoked (first argument after script).
   */
  readonly subcommand: string | undefined;

  /**
   * Remaining arguments after the subcommand, to be interpreted as flags
   * or positional arguments for that subcommand.
   */
  readonly args: string[];
}

/**
 * Parse raw Node.js argv into a structured CLI input for the maintenance tools.
 *
 * This performs only minimal, predictable splitting to support higher-level
 * flag parsing in a safe and testable way.
 *
 * @param argv - Raw argv array, usually process.argv.
 * @returns ParsedCliInput with node, script, subcommand, and remaining args.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
export function parseCliInput(argv: string[]): ParsedCliInput {
  const [node = "", script = "", ...rest] = argv;
  const [subcommand, ...args] = rest;
  return { argv, node, script, subcommand, args };
}

/**
 * Normalized view of CLI arguments relevant to a maintenance subcommand.
 *
 * This strips away Node/V8 internals and script paths, exposing only the
 * subcommand name and its raw arguments for further flag parsing.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
export interface NormalizedCliArgs {
  /**
   * The maintenance subcommand being invoked (first argument after script).
   */
  readonly subcommand: string | undefined;

  /**
   * Remaining arguments after the subcommand, to be interpreted as flags
   * or positional arguments for that subcommand.
   */
  readonly args: string[];
}

/**
 * Normalize raw argv into a subcommand-centric view for flag parsing.
 *
 * Uses parseCliInput to safely separate Node/V8 internals from the
 * subcommand and its arguments, then exposes only the pieces relevant
 * to subcommand-specific flag parsing.
 *
 * @param rawArgv - Raw argv array, usually process.argv.
 * @returns NormalizedCliArgs with subcommand and remaining args.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
export function normalizeCliArgs(rawArgv: string[]): NormalizedCliArgs {
  const { subcommand, args } = parseCliInput(rawArgv);
  return { subcommand, args };
}

export interface ParsedFlags {
  root: string;
  json: boolean;
  format?: "text" | "json";
  from?: string;
  to?: string;
  dryRun?: boolean;
}

/**
 * Initialize default flags for the maintenance CLI.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function createDefaultFlags(): ParsedFlags {
  return {
    root: process.cwd(),
    json: false,
  };
}

/**
 * Safely check if the next argument value exists and is a string.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function isNextValueString(args: string[], index: number): boolean {
  return typeof args[index + 1] === "string";
}

/**
 * Handle the --root flag, updating the root path if present.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function handleRootFlag(flags: ParsedFlags, args: string[], index: number): number {
  if (args[index] !== "--root" || !isNextValueString(args, index)) {
    return index;
  }

  flags.root = path.resolve(args[index + 1]);
  return index + 1;
}

/**
 * Handle the --json flag, toggling JSON output when present.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function handleJsonFlag(flags: ParsedFlags, args: string[], index: number): number {
  if (args[index] !== "--json") {
    return index;
  }

  flags.json = true;
  return index;
}

/**
 * Handle the --format flag, validating and setting the output format.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function handleFormatFlag(flags: ParsedFlags, args: string[], index: number): number {
  if (args[index] !== "--format" || !isNextValueString(args, index)) {
    return index;
  }

  const value = args[index + 1];
  if (value === "text" || value === "json") {
    flags.format = value;
  } else {
    throw new Error(`Invalid format: ${value}. Expected 'text' or 'json'.`);
  }

  return index + 1;
}

/**
 * Handle the --from flag, capturing the starting reference if present.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function handleFromFlag(flags: ParsedFlags, args: string[], index: number): number {
  if (args[index] !== "--from" || !isNextValueString(args, index)) {
    return index;
  }

  flags.from = args[index + 1];
  return index + 1;
}

/**
 * Handle the --to flag, capturing the ending reference if present.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function handleToFlag(flags: ParsedFlags, args: string[], index: number): number {
  if (args[index] !== "--to" || !isNextValueString(args, index)) {
    return index;
  }

  flags.to = args[index + 1];
  return index + 1;
}

/**
 * Handle the --dry-run flag, enabling dry-run mode when present.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function handleDryRunFlag(flags: ParsedFlags, args: string[], index: number): number {
  if (args[index] !== "--dry-run") {
    return index;
  }

  flags.dryRun = true;
  return index;
}

/**
 * Handle a single CLI argument and update the flags accordingly.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
function applyFlag(flags: ParsedFlags, args: string[], index: number): number {
  const afterRoot = handleRootFlag(flags, args, index);
  if (afterRoot !== index) {
    return afterRoot;
  }

  const afterJson = handleJsonFlag(flags, args, index);
  if (afterJson !== index) {
    return afterJson;
  }

  const afterFormat = handleFormatFlag(flags, args, index);
  if (afterFormat !== index) {
    return afterFormat;
  }

  const afterFrom = handleFromFlag(flags, args, index);
  if (afterFrom !== index) {
    return afterFrom;
  }

  const afterTo = handleToFlag(flags, args, index);
  if (afterTo !== index) {
    return afterTo;
  }

  const afterDryRun = handleDryRunFlag(flags, args, index);
  if (afterDryRun !== index) {
    return afterDryRun;
  }

  return index;
}

/**
 * Basic flag parser for maintenance CLI subcommands.
 *
 * Consumes already-normalized CLI arguments (subcommand and its raw args)
 * and produces a ParsedFlags structure with minimal, predictable behavior.
 *
 * @param normalized - Normalized CLI arguments for a maintenance subcommand.
 * @returns ParsedFlags with defaults applied and any recognized flags set.
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-SAFE - Provide predictable, minimal argument parsing
 */
export function parseFlags(normalized: NormalizedCliArgs): ParsedFlags {
  const flags: ParsedFlags = createDefaultFlags();
  const { args } = normalized;

  for (let i = 0; i < args.length; i += 1) {
    i = applyFlag(flags, args, i);
  }

  return flags;
}

import { detectStaleAnnotations } from "./detect";

/**
 * Generate a report of maintenance operations performed
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-REPORT - Generate maintenance report
 * @req REQ-MAINT-SAFE - Ensure operations are safe and reversible
 * @param codebasePath The workspace root to scan for stale maintenance annotations.
 * @returns An empty string when no stale annotations are found, or a newline-separated list of stale `@story` paths.
 */
export function generateMaintenanceReport(codebasePath: string): string {
  const staleAnnotations = detectStaleAnnotations(codebasePath);
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md // @req REQ-MAINT-SAFE - When no stale annotations are found, return empty string to indicate no actions required
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md // @req REQ-MAINT-REPORT - When stale annotations exist, produce a newline-separated report
  if (staleAnnotations.length === 0) {
    return "";
  }
  return staleAnnotations.join("\n");
}

import * as fs from "fs";
import { getAllFiles } from "./utils";

/**
 * Helper to process a single file for annotation reference updates
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-UPDATE
 */
function processFileForAnnotationUpdates(
  fullPath: string,
  regex: RegExp,
  newPath: string,
  replacementCountRef: { count: number },
): void {
  const stat = fs.statSync(fullPath);
  /**
   * Skip non-files in iteration
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UPDATE
   */
  /**
   * Skip entries that are not regular files (e.g., directories)
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UPDATE
   */
  if (!stat.isFile()) return;

  const content = fs.readFileSync(fullPath, "utf8");
  const newContent = content.replace(
    regex,
    /**
     * Replacement callback to update annotation references
     * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
     * @req REQ-MAINT-UPDATE
     */
    (match, p1) => {
      replacementCountRef.count++;
      return `${p1}${newPath}`;
    },
  );
  /**
   * Write file only if content changed
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UPDATE
   */
  if (newContent !== content) {
    fs.writeFileSync(fullPath, newContent, "utf8");
  }
}

/**
 * Update annotation references when story files are moved or renamed
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-UPDATE - Update annotation references
 * @param codebasePath Absolute or workspace-root path whose files will be updated in-place.
 * @param oldPath The original @story path to search for in annotation comments.
 * @param newPath The replacement @story path that will replace occurrences of oldPath.
 * @returns The number of @story annotations that were updated across the codebase.
 */
export function updateAnnotationReferences(
  codebasePath: string,
  oldPath: string,
  newPath: string,
): number {
  /**
   * Check that the provided codebase path exists and is a directory.
   * If not, abort early.
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UPDATE
   */
  // @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
  // @req REQ-MAINT-UPDATE
  if (
    !fs.existsSync(codebasePath) ||
    !fs.statSync(codebasePath).isDirectory()
  ) {
    return 0;
  }

  const replacementCountRef = { count: 0 };
  const escapedOldPath = oldPath.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const regex = new RegExp(`(@story\\s*)${escapedOldPath}`, "g");

  const files = getAllFiles(codebasePath);
  /**
   * Iterate over all files and replace annotation references
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UPDATE
   */
  /**
   * Loop over each discovered file path
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UPDATE
   */
  for (const fullPath of files) {
    processFileForAnnotationUpdates(
      fullPath,
      regex,
      newPath,
      replacementCountRef,
    );
  }

  return replacementCountRef.count;
}

import * as fs from "fs";
import * as path from "path";

/**
 * Recursively retrieve all files in a directory.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-UTILS - Extract common file traversal logic for maintenance tools
 */
export function getAllFiles(dir: string): string[] {
  const fileList: string[] = [];
  /**
   * Ensure the provided path exists and is a directory before traversal.
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UTILS-VALIDATE-DIR - Validate input directory path
   */
  /**
   * Traceability for the directory-existence branch.
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UTILS-VALIDATE-DIR-BRANCH - Traceability for directory-existence branch
   */
  if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) {
    return fileList;
  }

  traverseDirectory(dir, fileList);

  return fileList;
}

/**
 * Recursively traverse a directory and collect file paths.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINT-UTILS-TRAVERSE - Helper traversal function used by getAllFiles
 */
function traverseDirectory(currentDir: string, fileList: string[]): void {
  const entries = fs.readdirSync(currentDir);
  /**
   * Iterate over directory entries using a for-of loop.
   * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
   * @req REQ-MAINT-UTILS-TRAVERSE-FOROF - Traceability for ForOfStatement branch handling entries
   */
  for (const entry of entries) {
    const fullPath = path.join(currentDir, entry);
    const stat = fs.statSync(fullPath);
    /**
     * Recurse into directories to continue traversal.
     * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
     * @req REQ-MAINT-UTILS-TRAVERSE-DIR - Handle directory entries during traversal
     */
    if (stat.isDirectory()) {
      traverseDirectory(fullPath, fileList);
      /**
       * Collect regular file entries during traversal.
       * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
       * @req REQ-MAINT-UTILS-TRAVERSE-FILE - Handle file entries during traversal
       */
    }
    /**
     * Skip non-file entries encountered during traversal.
     * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
     * @req REQ-MAINT-UTILS-TRAVERSE-SKIP-NONFILE - Traceability for skipping non-file entries
     */
    if (!stat.isFile()) {
      continue;
    }
    fileList.push(fullPath);
  }
}

/**
 * Create a fixer function that inserts a @story annotation before the target node.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-AUTOFIX - Provide automatic fix function for missing @story annotations
 */
export function createAddStoryFix(target: any, annotationTemplate: string) {
  /**
   * Fixer that inserts a @story annotation before the target node.
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-AUTOFIX - Provide automatic fix function for missing @story annotations
   */

  function addStoryFixer(fixer: any) {
    const start =
      target && typeof target === "object"
        ? target.parent &&
          (target.parent.type === "ExportNamedDeclaration" ||
            target.parent.type === "ExportDefaultDeclaration") &&
          Array.isArray(target.parent.range) &&
          typeof target.parent.range[0] === "number"
          ? target.parent.range[0]
          : Array.isArray(target.range) && typeof target.range[0] === "number"
            ? target.range[0]
            : 0
        : 0;
    return fixer.insertTextBeforeRange(
      [start, start],
      `${annotationTemplate}\n`,
    );
  }
  return addStoryFixer;
}

/**
 * Create a fixer function for class method annotations.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-AUTOFIX - Provide automatic fix for class method annotations
 */
export function createMethodFix(node: any, annotationTemplate: string) {
  /**
   * Fixer that inserts a @story annotation before a method node.
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-AUTOFIX - Provide automatic fix for class method annotations
   */

  function methodFixer(fixer: any) {
    const start =
      node && typeof node === "object"
        ? node.parent &&
          (node.parent.type === "ExportNamedDeclaration" ||
            node.parent.type === "ExportDefaultDeclaration") &&
          Array.isArray(node.parent.range) &&
          typeof node.parent.range[0] === "number"
          ? node.parent.range[0]
          : Array.isArray(node.range) && typeof node.range[0] === "number"
            ? node.range[0]
            : 0
        : 0;
    return fixer.insertTextBeforeRange(
      [start, start],
      `${annotationTemplate}\n  `,
    );
  }
  return methodFixer;
}

/**
 * Default set of node types to check for missing @story annotations.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Provide sensible default scope for rule checks
 */
export const DEFAULT_SCOPE: string[] = [
  "FunctionDeclaration",
  "FunctionExpression",
  "MethodDefinition",
  "TSMethodSignature",
  "TSDeclareFunction",
];

/**
 * Allowed values for export priority option.
 */
export const EXPORT_PRIORITY_VALUES = ["all", "exported", "non-exported"];

/**
 * Helpers for the "require-story" rule
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @req REQ-ANNOTATION-REQUIRED - File-level header for rule helper utilities
 * @req REQ-AUTOFIX-MISSING
 * @req REQ-AUTOFIX-TEMPLATE
 * @req REQ-AUTOFIX-SELECTIVE
 */
import type { Rule } from "eslint";
import {
  linesBeforeHasStory,
  parentChainHasStory,
  fallbackTextBeforeHasStory,
} from "./require-story-io";
import { getNodeName } from "./require-story-utils";

import {
  DEFAULT_SCOPE,
  EXPORT_PRIORITY_VALUES,
  createAddStoryFix,
  createMethodFix,
} from "./require-story-core";

/**
 * Path to the story file for annotations
 */
const STORY_PATH = "docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md";

/**
 * Derive the annotation template, optionally using an override.
 * When override is a non-empty string, its trimmed value is used.
 * Otherwise, the default template is returned.
 */
function getAnnotationTemplate(override?: string): string {
  if (typeof override === "string" && override.trim().length > 0) {
    return override.trim();
  }
  return `/** @story ${STORY_PATH} */`;
}

/**
 * Determine whether auto-fix should be applied.
 * Explicit false disables auto-fix; all other values enable it.
 */
function shouldApplyAutoFix(autoFix: boolean | undefined): boolean {
  if (autoFix === false) {
    return false;
  }
  return true;
}

/**
 * Number of physical source lines to inspect before a node when searching for @story text
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Replace magic number for lookback lines with named constant
 */
const LOOKBACK_LINES = 4;

/**
 * Window (in characters) to inspect before a node as a fallback when searching for @story text
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Replace magic number for fallback text window with named constant
 */
const FALLBACK_WINDOW = 800;

/**
 * Determine if a node is in an export declaration
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Check node ancestry to find export declarations
 * @param {any} node - AST node to check for export ancestry
 * @returns {boolean} true if node is within an export declaration
 */
function isExportedNode(node: any): boolean {
  let p = node.parent;
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQUIRED - Walk parent chain to find Export declarations
  while (p) {
    if (
      p.type === "ExportNamedDeclaration" ||
      p.type === "ExportDefaultDeclaration"
    ) {
      return true;
    }
    p = p.parent;
  }
  return false;
}

/**
 * Check whether the JSDoc associated with node contains @story
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Extract JSDoc based detection into helper
 * @param {any} sourceCode - ESLint sourceCode object
 * @param {any} node - AST node to inspect
 * @returns {boolean} true if JSDoc contains @story
 */
function jsdocHasStory(sourceCode: any, node: any): boolean {
  if (typeof sourceCode?.getJSDocComment !== "function") {
    return false;
  }
  const jsdoc = sourceCode.getJSDocComment(node);
  return !!(
    jsdoc &&
    typeof jsdoc.value === "string" &&
    jsdoc.value.includes("@story")
  );
}

/**
 * Check whether comments returned by sourceCode.getCommentsBefore contain @story
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Extract comment-before detection into helper
 * @param {any} sourceCode - ESLint sourceCode object
 * @param {any} node - AST node to inspect
 * @returns {boolean} true if any preceding comment contains @story
 */
function commentsBeforeHasStory(sourceCode: any, node: any): boolean {
  if (typeof sourceCode?.getCommentsBefore !== "function") {
    return false;
  }
  const commentsBefore = sourceCode.getCommentsBefore(node) || [];
  return (
    Array.isArray(commentsBefore) &&
    commentsBefore.some(
      (c: any) => typeof c.value === "string" && c.value.includes("@story"),
    )
  );
}

/**
 * Check whether leadingComments attached to the node contain @story
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Extract leadingComments detection into helper
 * @param {any} node - AST node to inspect
 * @returns {boolean} true if any leading comment contains @story
 */
function leadingCommentsHasStory(node: any): boolean {
  const leadingComments = (node && node.leadingComments) || [];
  return (
    Array.isArray(leadingComments) &&
    leadingComments.some(
      (c: any) => typeof c.value === "string" && c.value.includes("@story"),
    )
  );
}

/**
 * Check if @story annotation already present in JSDoc or preceding comments
 * Consolidates a variety of heuristics through smaller helpers.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Detect existing story annotations in JSDoc or comments
 * @param {any} sourceCode - ESLint sourceCode object
 * @param {any} node - AST node to inspect for existing annotations
 * @returns {boolean} true if @story annotation already present
 */
function hasStoryAnnotation(sourceCode: any, node: any): boolean {
  try {
    if (jsdocHasStory(sourceCode, node)) {
      return true;
    }
    if (commentsBeforeHasStory(sourceCode, node)) {
      return true;
    }
    if (leadingCommentsHasStory(node)) {
      return true;
    }
    if (linesBeforeHasStory(sourceCode, node, LOOKBACK_LINES)) {
      return true;
    }
    if (parentChainHasStory(sourceCode, node)) {
      return true;
    }
    if (fallbackTextBeforeHasStory(sourceCode, node)) {
      return true;
    }
  } catch {
    /* noop */
  }

  return false;
}

/**
 * Determine AST node where annotation should be inserted
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Determine correct insertion target for annotation
 * @param {any} sourceCode - ESLint sourceCode object (unused but kept for parity)
 * @param {any} node - function-like AST node to resolve target for
 * @returns {any} AST node that should receive the annotation
 */
function resolveTargetNode(sourceCode: any, node: any): any {
  if (node.type === "TSMethodSignature") {
    // Interface method signature -> insert on interface
    return node.parent.parent;
  }
  if (
    node.type === "FunctionExpression" ||
    node.type === "ArrowFunctionExpression"
  ) {
    const parent = node.parent;
    if (parent.type === "VariableDeclarator") {
      const varDecl = parent.parent;
      if (varDecl.parent && varDecl.parent.type === "ExportNamedDeclaration") {
        return varDecl.parent;
      }
      return varDecl;
    }
    if (parent.type === "ExportNamedDeclaration") {
      return parent;
    }
    if (parent.type === "ExpressionStatement") {
      return parent;
    }
  }
  return node;
}

function isIdentifierWithName(node: any): node is { type: string; name: string } {
  return node?.type === "Identifier" && typeof node.name === "string";
}

function hasIdIdentifierWithName(node: any): boolean {
  return Boolean(node?.id && isIdentifierWithName(node.id));
}

function hasKeyIdentifierWithName(node: any): boolean {
  return Boolean(node?.key && isIdentifierWithName(node.key));
}

function hasLiteralKeyWithStringValue(node: any): boolean {
  return Boolean(
    node?.key &&
      node.key.type === "Literal" &&
      typeof (node.key as any).value === "string",
  );
}

/**
 * Small utility to walk the node and its parents to extract an Identifier or key name.
 * Walks up the parent chain and inspects common properties (id, key, name, Identifier nodes).
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Walk node and parents to find Identifier/Key name
 * @param {any} node - AST node to extract a name from
 * @returns {string} extracted name or "(anonymous)" when no name found
 */
function extractName(node: any): string {
  let current: any = node;

  while (current) {
    if (isIdentifierWithName(current)) {
      return current.name;
    }

    if (hasIdIdentifierWithName(current)) {
      return current.id.name;
    }

    if (hasKeyIdentifierWithName(current)) {
      return current.key.name;
    }

    const directName = (current as any).name;
    if (typeof directName === "string" && directName.length > 0) {
      return directName;
    }

    if (hasLiteralKeyWithStringValue(current)) {
      return (current.key as any).value;
    }

    current = current.parent;
  }

  return "(anonymous)";
}

/**
 * Check if this node is within scope and matches exportPriority
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Determine whether a node should be processed by rule
 * @param {any} node - AST node to evaluate
 * @param {string[]} scope - allowed node types
 * @param {string} [exportPriority='all'] - 'all' | 'exported' | 'non-exported' (default: 'all')
 * @returns {boolean} whether node should be processed
 */
function shouldProcessNode(
  node: any,
  scope: string[],
  exportPriority: string = "all",
): boolean {
  if (!scope.includes(node.type)) {
    return false;
  }
  const exported = isExportedNode(node);
  if (exportPriority === "exported" && !exported) {
    return false;
  }
  if (exportPriority === "non-exported" && exported) {
    return false;
  }
  return true;
}

interface ReportOptions {
  annotationTemplateOverride?: string;
  autoFixToggle?: boolean;
}

/**
 * Resolve the effective function name to report for a node.
 * Normalizes id/key handling before delegating to extractName.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Centralize reported function name resolution
 * @param {any} node - AST node used to derive the function name
 * @returns {string} resolved function name
 */
function getReportedFunctionName(node: any): string {
  const candidate = node && (node.id || node.key) ? node.id || node.key : node;
  return extractName(candidate);
}

/**
 * Determine the most appropriate AST node to anchor error location for a report.
 * Prefers Identifier nodes from id/key properties when available.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Normalize name node selection for error reporting
 * @param {any} node - AST node used for error anchoring
 * @returns {any} node to use as the report location
 */
function getNameNodeForReport(node: any): any {
  if (node?.id?.type === "Identifier") {
    return node.id;
  }

  if (node?.key?.type === "Identifier") {
    return node.key;
  }

  return node;
}

/**
 * Resolve the node that should receive the @story annotation,
 * respecting an explicitly passed target when provided.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Centralize annotation target node resolution
 * @param {any} sourceCode - ESLint sourceCode object
 * @param {any} node - original function-like AST node
 * @param {any} passedTarget - optional explicit annotation target
 * @returns {any} node that should receive the annotation
 */
function resolveAnnotationTargetNode(
  sourceCode: any,
  node: any,
  passedTarget: any,
): any {
  return passedTarget ?? resolveTargetNode(sourceCode, node);
}

/**
 * Build the effective annotation template and autofix toggle
 * from the provided report options.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Normalize template and autofix configuration
 * @param {ReportOptions} [options] - optional report configuration
 * @returns {{ effectiveTemplate: string; allowFix: boolean }} template and autofix flags
 */
function buildTemplateConfig(options?: ReportOptions): {
  effectiveTemplate: string;
  allowFix: boolean;
} {
  const effectiveTemplate = getAnnotationTemplate(
    options?.annotationTemplateOverride,
  );
  const allowFix = shouldApplyAutoFix(options?.autoFixToggle);

  return { effectiveTemplate, allowFix };
}

/**
 * Report a missing @story annotation for a function-like node
 * Provides a suggestion to add the annotation.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/007.0-DEV-ERROR-REPORTING.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @req REQ-ANNOTATION-REQUIRED - Implement reporting for missing annotations with suggestion
 * @req REQ-AUTOFIX-MISSING - Provide autofix for missing annotations while preserving suggestions
 * @req REQ-ERROR-SPECIFIC - Error reports must include both name and functionName in the data payload for specific function context
 * @param {Rule.RuleContext} context - ESLint rule context used to report
 * @param {any} sourceCode - ESLint sourceCode object
 * @param {{ node: any; target?: any; options?: ReportOptions }} config - configuration containing the node to report, optional insertion target, and optional report options
 */
function reportMissing(
  context: Rule.RuleContext,
  sourceCode: any,
  config: { node: any; target?: any; options?: ReportOptions },
): void {
  const { node, target: passedTarget, options = {} } = config;

  try {
    if (hasStoryAnnotation(sourceCode, node)) {
      return;
    }

    const functionName = getReportedFunctionName(node);
    const resolvedTarget = resolveAnnotationTargetNode(
      sourceCode,
      node,
      passedTarget,
    );
    const nameNode = getNameNodeForReport(node);
    const { effectiveTemplate, allowFix } = buildTemplateConfig(options);
    const name = functionName;

    context.report({
      node: nameNode,
      messageId: "missingStory",
      data: { name, functionName: name },
      fix: allowFix
        ? createAddStoryFix(resolvedTarget, effectiveTemplate)
        : undefined,
      suggest: [
        {
          desc: `Add JSDoc @story annotation for function '${name}', e.g., ${effectiveTemplate}`,
          fix: createAddStoryFix(resolvedTarget, effectiveTemplate),
        },
      ],
    });
  } catch {
    /* noop */
  }
}

/**
 * Report a missing @story annotation for a method-like node
 * Provides a suggestion to update the method/interface with the annotation.
 * The error data payload uses both name and functionName for consistent, specific error context.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/007.0-DEV-ERROR-REPORTING.story.md
 * @req REQ-ANNOTATION-REQUIRED - Implement reporting for missing method/interface annotations with suggestion
 * @req REQ-AUTOFIX-MISSING - Provide autofix for missing method/interface annotations while preserving suggestions
 * @req REQ-ERROR-SPECIFIC - Method error reports must include both name and functionName in the data payload for specific function context
 * @req REQ-ERROR-LOCATION - Method error reports must use the method name node to anchor error location
 * @req REQ-ERROR-CONTEXT - Method error reports must include functionName data for consistent error context
 * @param {Rule.RuleContext} context - ESLint rule context to report
 * @param {any} sourceCode - ESLint sourceCode object
 * @param {{ node: any; target?: any; options?: ReportOptions }} config - configuration containing the node to report, optional insertion target, and optional report options
 */
function reportMethod(
  context: Rule.RuleContext,
  sourceCode: any,
  config: { node: any; target?: any; options?: ReportOptions },
): void {
  const { node, target: passedTarget, options = {} } = config;

  try {
    if (hasStoryAnnotation(sourceCode, node)) {
      return;
    }
    const resolvedTarget = passedTarget ?? resolveTargetNode(sourceCode, node);
    const name = extractName(node);
    const nameNode =
      (node.key && node.key.type === "Identifier" && node.key) || node;

    const effectiveTemplate = getAnnotationTemplate(
      options.annotationTemplateOverride,
    );
    const allowFix = shouldApplyAutoFix(options.autoFixToggle);

    context.report({
      node: nameNode,
      messageId: "missingStory",
      data: { name, functionName: name },
      fix: allowFix
        ? createMethodFix(resolvedTarget, effectiveTemplate)
        : undefined,
      suggest: [
        {
          desc: `Add JSDoc @story annotation for function '${name}', e.g., ${effectiveTemplate}`,
          fix: createMethodFix(resolvedTarget, effectiveTemplate),
        },
      ],
    });
  } catch {
    /* noop */
  }
}

/**
 * Explicit exports for require-story-annotation consumers
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Explicitly export helper functions and constants used by requiring modules
 */
export {
  STORY_PATH,
  getAnnotationTemplate,
  shouldApplyAutoFix,
  LOOKBACK_LINES,
  FALLBACK_WINDOW,
  isExportedNode,
  jsdocHasStory,
  commentsBeforeHasStory,
  leadingCommentsHasStory,
  hasStoryAnnotation,
  getNodeName,
  extractName,
  resolveTargetNode,
  shouldProcessNode,
  reportMissing,
  reportMethod,
  DEFAULT_SCOPE,
  EXPORT_PRIORITY_VALUES,
  linesBeforeHasStory,
  parentChainHasStory,
  fallbackTextBeforeHasStory,
};

/**
 * IO helpers for require-story detection moved to reduce helper module size
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Extract IO bound helpers to separate module
 */

/**
 * Number of source lines to inspect before a node when searching for @story markers.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Expose lookback size as constant for reuse
 */
export const LOOKBACK_LINES = 4;

/**
 * Number of characters to include in the fallback textual inspection window before a node.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Expose fallback window size as constant for reuse
 */
export const FALLBACK_WINDOW = 800;

/**
 * Shared predicate to determine if a given comment node contains an @story marker.
 * Also treats @supports annotations as satisfying story presence checks.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-ANNOTATION-REQUIRED - Centralize @story detection logic for comment value inspection
 * @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Treat @supports annotations as satisfying story presence checks
 */
function commentContainsStory(comment: any): boolean {
  if (typeof comment?.value !== "string") {
    return false;
  }
  return (
    comment.value.includes("@story") || comment.value.includes("@supports")
  );
}

/**
 * Safely extract the physical source lines array from sourceCode for scanning.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Centralize guards for safe access to source lines
 */
function getSourceLines(sourceCode: any): string[] | null {
  const lines = sourceCode && sourceCode.lines;
  return Array.isArray(lines) ? lines : null;
}

/**
 * Safely resolve the starting line number of a node for use in lookback scans.
 * Returns null when the node does not provide a valid numeric start line.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Centralize guards for safe access to node location metadata
 */
function getNodeStartLine(node: any): number | null {
  if (!node || !node.loc) {
    return null;
  }
  const line = node.loc.start?.line;
  return typeof line === "number" ? line : null;
}

/**
 * Generic helper to scan a range of physical source lines for the presence of an @story marker.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Reuse line scanning logic for story annotations across helpers
 * @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Accept @supports annotations as valid markers during line scanning
 */
function scanLinesForMarker(
  lines: string[],
  from: number,
  to: number,
): boolean {
  // Walk each physical line in the configured lookback window to search for an inline @story or @supports marker.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQUIRED - Scan preceding lines for existing story annotations
  for (let i = from; i < to; i++) {
    const text = lines[i];
    // Treat any line containing "@story" or "@supports" as evidence that the function is already annotated.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQUIRED - Detect explicit @story markers in raw source text
    // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Detect explicit @supports markers in raw source text
    if (
      typeof text === "string" &&
      (text.includes("@story") || text.includes("@supports"))
    ) {
      return true;
    }
  }
  return false;
}

/**
 * Inspect a fixed number of physical source lines before the node for @story text
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Extract line-based detection into helper
 */
export function linesBeforeHasStory(
  sourceCode: any,
  node: any,
  lookback = LOOKBACK_LINES,
): boolean {
  const lines = getSourceLines(sourceCode);
  const startLine = getNodeStartLine(node);
  // Guard against missing or non-array source lines or an invalid start line before scanning.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQUIRED - Fail gracefully when source lines or locations are unavailable
  if (!lines || typeof startLine !== "number") {
    return false;
  }
  const from = Math.max(0, startLine - 1 - lookback);
  const to = Math.max(0, startLine - 1);
  return scanLinesForMarker(lines, from, to);
}

/**
 * Walk parent chain and check comments before each parent and their leadingComments
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Extract parent-chain comment detection into helper
 */
export function parentChainHasStory(sourceCode: any, node: any): boolean {
  let p = node && node.parent;
  while (p) {
    const pComments =
      typeof sourceCode?.getCommentsBefore === "function"
        ? sourceCode.getCommentsBefore(p) || []
        : [];
    if (
      Array.isArray(pComments) &&
      pComments.some(
        /**
         * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
         * @req REQ-ANNOTATION-REQUIRED - Detect @story in parent comments via value inspection
         */
        (c: any) => commentContainsStory(c),
      )
    ) {
      return true;
    }
    const pLeading = p.leadingComments || [];
    if (
      Array.isArray(pLeading) &&
      pLeading.some(
        /**
         * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
         * @req REQ-ANNOTATION-REQUIRED - Detect @story in parent leadingComments via value inspection
         */
        (c: any) => commentContainsStory(c),
      )
    ) {
      return true;
    }
    p = p.parent;
  }
  return false;
}

/**
 * Fallback: inspect text immediately preceding the node in sourceCode.getText to find @story
 * Also accepts @supports annotations as satisfying story presence for this rule.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-ANNOTATION-REQUIRED - Provide fallback textual inspection when other heuristics fail
 * @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Treat @supports annotations as satisfying story presence in fallback checks
 */
export function fallbackTextBeforeHasStory(
  sourceCode: any,
  node: any,
): boolean {
  // Skip fallback text inspection when the sourceCode API or node range information is not available.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQUIRED - Avoid throwing when source text or range metadata cannot be read
  if (
    typeof sourceCode?.getText !== "function" ||
    !Array.isArray((node && node.range) || [])
  ) {
    return false;
  }
  const range = node.range;
  // Guard against malformed range values that cannot provide a numeric start index for slicing.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQUIRED - Validate node range structure before computing fallback window
  if (!Array.isArray(range) || typeof range[0] !== "number") {
    return false;
  }
  try {
    // Limit the fallback inspection window to a bounded region immediately preceding the node.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQUIRED - Restrict fallback text scanning to a safe, fixed-size window
    const start = Math.max(0, range[0] - FALLBACK_WINDOW);
    const textBefore = sourceCode.getText().slice(start, range[0]);
    // Detect any @story or @supports marker that appears within the bounded fallback window.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQUIRED - Recognize story annotations discovered via fallback text scanning
    // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Recognize @supports annotations discovered via fallback text scanning
    if (
      typeof textBefore === "string" &&
      (textBefore.includes("@story") || textBefore.includes("@supports"))
    ) {
      return true;
    }
  } catch {
    /*
     * Swallow low-level IO or slicing errors so annotation detection never breaks lint execution.
     * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
     * @req REQ-ANNOTATION-REQUIRED - Treat fallback text inspection failures as "no annotation" instead of raising
     */
  }
  return false;
}

/**
 * src/rules/helpers/require-story-utils.ts
 *
 * Utility: getNodeName
 *
 * Traceability:
 * - File: src/rules/helpers/require-story-utils.ts
 * - Purpose: Helper used by rules to obtain a readable "name" from various AST node shapes.
 * - Created to centralize logic for extracting identifier/property/literal names from ESTree / TSESTree nodes.
 *
 * Docs/Annotations:
 * - Story: docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * - Requirement annotation: REQ-ANNOTATION-REQUIRED
 *
 * Behavior:
 * - Accepts common AST node shapes (Identifier, Literal, Property, MemberExpression, TemplateLiteral, JSXIdentifier, etc.)
 * - Returns a string name when it can be reasonably determined, otherwise returns null.
 *
 * Notes:
 * - This helper is intentionally defensive and conservative: when the node is computed or contains expressions
 *   that cannot be resolved statically, it returns null.
 * - The function uses weak typing for the node parameter to maximize compatibility with different AST types
 *   (ESTree, TSESTree, JSX variations).
 */

/**
 * Check for identifier-like nodes and return their name when available.
 *
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Recognize Identifier/JSXIdentifier nodes and return their name
 *
 * @param node - AST node to inspect
 * @returns the identifier name or null
 */
function isIdentifierLike(node: any): string | null {
  if (!node) return null;
  const type = node.type;
  if (type === "Identifier" || type === "JSXIdentifier") {
    return typeof node.name === "string" ? node.name : null;
  }
  return null;
}

/**
 * Convert a Literal node to a string when it represents a stable primitive (string/number/boolean).
 *
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Convert simple Literal nodes into stable string names when possible
 *
 * @param node - AST node expected to be a Literal
 * @returns the literal as string or null if not stable/resolvable
 */
function literalToString(node: any): string | null {
  if (!node || node.type !== "Literal") return null;
  const val = node.value;
  if (val === null) return null;
  const t = typeof val;
  return t === "string" || t === "number" || t === "boolean"
    ? String(val)
    : null;
}

/**
 * Convert a TemplateLiteral node to a string if it contains no expressions.
 *
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Support simple, expression-free TemplateLiteral names for reporting
 *
 * @param node - AST node expected to be a TemplateLiteral
 * @returns the cooked/raw concatenated template string or null if it contains expressions
 */
function templateLiteralToString(node: any): string | null {
  if (!node || node.type !== "TemplateLiteral") return null;
  const expressions = node.expressions || [];
  if (expressions.length !== 0) return null;
  const quasis = node.quasis || [];
  return quasis
    .map((q: any) => {
      if (!q || !q.value) return "";
      if (typeof q.value.cooked === "string") return q.value.cooked;
      if (typeof q.value.raw === "string") return q.value.raw;
      return "";
    })
    .join("");
}

/**
 * Resolve a MemberExpression / TSQualifiedName / JSXMemberExpression-like node to a name when non-computed.
 *
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Resolve non-computed member-like nodes into property names when safe
 *
 * @param node - AST node to inspect
 * @returns resolved member/property name or null
 */
function memberExpressionName(node: any): string | null {
  if (!node) return null;
  const type = node.type;
  if (
    type !== "MemberExpression" &&
    type !== "TSQualifiedName" &&
    type !== "JSXMemberExpression"
  ) {
    return null;
  }
  // For TSQualifiedName and JSXMemberExpression, treat like non-computed access.
  if (
    type === "TSQualifiedName" ||
    type === "JSXMemberExpression" ||
    node.computed === false
  ) {
    return getNodeName(node.property || node.right);
  }
  return null;
}

/**
 * Extract the key name from Property/ObjectProperty nodes.
 *
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Extract key names from Property/ObjectProperty nodes used in function containers
 *
 * @param node - AST node expected to be Property/ObjectProperty
 * @returns the resolved key name or null
 */
function propertyKeyName(node: any): string | null {
  if (!node) return null;
  if (node.type === "Property" || node.type === "ObjectProperty") {
    return getNodeName(node.key);
  }
  return null;
}

/**
 * Extract direct-level names from common container fields (.id / .key) to reduce branching in getNodeName.
 *
 * Branch-level traceability: prefer direct .id.name when available (common on function/class declarations)
 * Branch-level traceability: prefer direct .key.name early (common on variable declarators, properties)
 *
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Prefer direct id/key names before falling back to deeper AST inspection
 *
 * @param node - AST node to inspect for direct .id/.key name
 * @returns the resolved direct name or null
 */
function directName(node: any): string | null {
  if (!node) return null;

  // Prefer direct .id.name when available
  if (node.id && typeof node.id.name === "string") {
    return node.id.name;
  }
  if (node.id) {
    const idName = getNodeName(node.id);
    if (idName !== null) return idName;
  }

  // Prefer direct .key.name early
  if (node.key && typeof node.key.name === "string") {
    return node.key.name;
  }
  if (node.key) {
    const keyName = getNodeName(node.key);
    if (keyName !== null) return keyName;
  }

  return null;
}

/**
 * Get a readable name for a given AST node.
 *
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQUIRED - Provide a unified way to obtain a stable, human-readable name from AST nodes
 *
 * @param node - An AST node (ESTree/TSESTree/JSX-like). Can be null/undefined.
 * @returns The resolved name string, or null if a stable name cannot be determined.
 */
export function getNodeName(node: any): string | null {
  if (!node) return null;

  // Delegate direct-level id/key resolution to helper to reduce cyclomatic complexity
  const direct = directName(node);
  if (direct !== null) return direct;

  // Identifier-like nodes
  const idName = isIdentifierLike(node);
  if (idName !== null) return idName;

  // Literal nodes
  const lit = literalToString(node);
  if (lit !== null) return lit;

  // TemplateLiteral nodes
  const tpl = templateLiteralToString(node);
  if (tpl !== null) return tpl;

  // Property-like nodes
  const prop = propertyKeyName(node);
  if (prop !== null) return prop;

  // Member/qualified/member-expression-like nodes
  const member = memberExpressionName(node);
  if (member !== null) return member;

  // TypeScript literal wrapper
  if (node.type === "TSLiteralType" && node.literal) {
    return getNodeName(node.literal);
  }

  // JSX namespaced name
  if (node.type === "JSXNamespacedName") {
    return getNodeName(node.name);
  }

  // Generic fallback: try .key if present on other shapes
  if (node.key) {
    return getNodeName(node.key);
  }

  return null;
}

/**
 * Visitor builders for require-story-annotation rule
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-EXTRACT-VISITORS - Extract visitor logic into helper module to reduce rule file size
 */

import type { Rule } from "eslint";
import {
  resolveTargetNode,
  reportMissing as helperReportMissing,
  reportMethod as helperReportMethod,
} from "./require-story-helpers";

/**
 * Build visitor for FunctionDeclaration nodes.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-BUILD-VISITORS-FNDECL - Provide visitor for FunctionDeclaration
 */
function buildFunctionDeclarationVisitor(
  context: Rule.RuleContext,
  sourceCode: any,
  options: any,
): Rule.RuleListener {
  /**
   * Handle FunctionDeclaration nodes.
   *
   * Developers who need to troubleshoot this handler may temporarily add
   * console.debug statements here, but by default no debug logging runs so that
   * file paths and other details are not leaked during normal linting.
   *
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-ANNOTATION-REQUIRED - Report missing @story on function declarations
   */
  function handleFunctionDeclaration(node: any) {
    if (!options.shouldProcessNode(node)) return;

    const target = resolveTargetNode(sourceCode, node);
    helperReportMissing(context, sourceCode, {
      node,
      target,
      options: {
        annotationTemplateOverride: options.annotationTemplate,
        autoFixToggle: options.autoFix,
      },
    });
  }

  return {
    FunctionDeclaration: handleFunctionDeclaration,
  };
}

/**
 * Build visitor for FunctionExpression nodes.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-BUILD-VISITORS-FNEXPR - Provide visitor for FunctionExpression
 */
function buildFunctionExpressionVisitor(
  context: Rule.RuleContext,
  sourceCode: any,
  options: any,
): Rule.RuleListener {
  /**
   * Handle FunctionExpression nodes.
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-ANNOTATION-REQUIRED - Report missing @story on function expressions
   */
  function handleFunctionExpression(node: any) {
    if (!options.shouldProcessNode(node)) return;

    /**
     * Do not report when function expression is a MethodDefinition
     * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
     * @req REQ-METHOD-SKIP - Skip MethodDefinition function expressions
     */
    if (node.parent && node.parent.type === "MethodDefinition") return;

    const target = resolveTargetNode(sourceCode, node);
    helperReportMissing(context, sourceCode, {
      node,
      target,
      options: {
        annotationTemplateOverride: options.annotationTemplate,
        autoFixToggle: options.autoFix,
      },
    });
  }

  return {
    FunctionExpression: handleFunctionExpression,
  };
}

/**
 * Build visitor for ArrowFunctionExpression nodes.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-BUILD-VISITORS-ARROW - Provide visitor for ArrowFunctionExpression
 */
function buildArrowFunctionVisitor(
  context: Rule.RuleContext,
  sourceCode: any,
  options: any,
): Rule.RuleListener {
  /**
   * Handle ArrowFunctionExpression nodes.
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-ANNOTATION-REQUIRED - Report missing @story on arrow functions
   */
  function handleArrowFunctionExpression(node: any) {
    if (!options.shouldProcessNode(node)) return;
    const target = resolveTargetNode(sourceCode, node);
    helperReportMissing(context, sourceCode, {
      node,
      target,
      options: {
        annotationTemplateOverride: options.annotationTemplate,
        autoFixToggle: options.autoFix,
      },
    });
  }

  return {
    ArrowFunctionExpression: handleArrowFunctionExpression,
  };
}

/**
 * Build visitor for TypeScript TSDeclareFunction nodes.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-BUILD-VISITORS-TSDECL - Provide visitor for TSDeclareFunction
 */
function buildTSDeclareFunctionVisitor(
  context: Rule.RuleContext,
  sourceCode: any,
  options: any,
): Rule.RuleListener {
  /**
   * Handle TSDeclareFunction nodes.
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-ANNOTATION-REQUIRED - Report missing @story on TS declare functions
   */
  function handleTSDeclareFunction(node: any) {
    if (!options.shouldProcessNode(node)) return;
    helperReportMissing(context, sourceCode, {
      node,
      target: node,
      options: {
        annotationTemplateOverride: options.annotationTemplate,
        autoFixToggle: options.autoFix,
      },
    });
  }

  return {
    TSDeclareFunction: handleTSDeclareFunction,
  };
}

/**
 * Build visitor for TypeScript TSMethodSignature nodes.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-BUILD-VISITORS-TSMSIG - Provide visitor for TSMethodSignature
 */
function buildTSMethodSignatureVisitor(
  context: Rule.RuleContext,
  sourceCode: any,
  options: any,
): Rule.RuleListener {
  /**
   * Handle TSMethodSignature nodes.
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-ANNOTATION-REQUIRED - Report missing @story on TS method signatures
   */
  function handleTSMethodSignature(node: any) {
    if (!options.shouldProcessNode(node)) return;
    const target = resolveTargetNode(sourceCode, node);
    helperReportMissing(context, sourceCode, {
      node,
      target,
      options: {
        annotationTemplateOverride:
          options.methodAnnotationTemplate ?? options.annotationTemplate,
        autoFixToggle: options.autoFix,
      },
    });
  }

  return {
    TSMethodSignature: handleTSMethodSignature,
  };
}

/**
 * Build visitor for MethodDefinition nodes.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-BUILD-VISITORS-METHODDEF - Provide visitor for MethodDefinition
 */
function buildMethodDefinitionVisitor(
  context: Rule.RuleContext,
  sourceCode: any,
  options: any,
): Rule.RuleListener {
  /**
   * Handle MethodDefinition nodes (class/object methods).
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-ANNOTATION-REQUIRED - Report missing @story on class/object methods
   */
  function handleMethodDefinition(node: any) {
    if (!options.shouldProcessNode(node)) return;
    helperReportMethod(context, sourceCode, {
      node,
      options: {
        annotationTemplateOverride:
          options.methodAnnotationTemplate ?? options.annotationTemplate,
        autoFixToggle: options.autoFix,
      },
    });
  }

  return {
    MethodDefinition: handleMethodDefinition,
  };
}

/**
 * Build visitor handlers for various function-like AST nodes.
 * Returns merged listener object from smaller builders.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-BUILD-VISITORS - Provide visitor implementations for rule create()
 */
export function buildVisitors(
  context: Rule.RuleContext,
  sourceCode: any,
  options: any,
): Rule.RuleListener {
  const fnDecl = buildFunctionDeclarationVisitor(context, sourceCode, options);
  const fnExpr = buildFunctionExpressionVisitor(context, sourceCode, options);
  const arrow = buildArrowFunctionVisitor(context, sourceCode, options);
  const tsDecl = buildTSDeclareFunctionVisitor(context, sourceCode, options);
  const tsSig = buildTSMethodSignatureVisitor(context, sourceCode, options);
  const methodDef = buildMethodDefinitionVisitor(context, sourceCode, options);

  return Object.assign({}, fnDecl, fnExpr, arrow, tsDecl, tsSig, methodDef);
}

/**
 * Helper utilities for the require-test-traceability rule.
 *
 * @supports docs/stories/020.0-DEV-TEST-ANNOTATION-VALIDATION.story.md REQ-TEST-PATTERN-DETECT REQ-TEST-FRAMEWORK-COMPAT
 * @supports docs/stories/021.0-DEV-TEST-ANNOTATION-AUTO-FIX.story.md REQ-TEST-FIX-TEMPLATE REQ-TEST-FIX-PREFIX-FORMAT REQ-TEST-FIX-SAFE REQ-TEST-FIX-PRESERVE REQ-TEST-FIX-PLACEHOLDER REQ-TEST-FIX-NO-INFERENCE
 */
const NOT_FOUND = -1;
const REQ_PREFIX_LENGTH = 3;
const QUOTES = ["'", '"', "`"] as const;

export type TestTraceabilityAutoFixOptions = {
  autoFixTestTemplate: boolean;
  testSupportsTemplate?: string;
};

export type CallExpressionOptions = {
  sourceCode: any;
  describeRegex: RegExp;
  requireDescribeStory: boolean;
  requireTestReqPrefix: boolean;
  autoFixTestPrefixFormat: boolean;
};

/**
 * Determine if a file should be treated as a test file based on patterns.
 *
 * @supports docs/stories/020.0-DEV-TEST-ANNOTATION-VALIDATION.story.md REQ-TEST-PATTERN-DETECT
 */
export function determineIsTestFile(
  filename: string,
  rawPatterns: string[] = [
    "/tests/",
    "/test/",
    "/__tests__",
    ".test.",
    ".spec.",
  ],
): boolean {
  return rawPatterns.some((pattern: string) =>
    filename.includes(pattern.replace("**", "")),
  );
}

/**
 * Build the placeholder @supports template comment for a test file.
 *
 * @supports docs/stories/021.0-DEV-TEST-ANNOTATION-AUTO-FIX.story.md REQ-TEST-FIX-TEMPLATE REQ-TEST-FIX-PLACEHOLDER
 */
function buildSupportsTemplateComment(customTemplate?: string): string {
  const baseTemplate =
    (customTemplate && customTemplate.trim()) ||
    "@supports docs/stories/XXX.X-STORY-NAME.story.md REQ-XXX-YYY REQ-XXX-ZZZ";

  const lines = [
    "/**",
    ` * ${baseTemplate}`,
    " * TODO: Replace the placeholder story path and REQ-IDs with real values for this test file.",
    " */",
    "",
  ];

  return lines.join("\n");
}

/**
 * Insert the file-level @supports template comment at a safe location.
 *
 * The template is inserted after a shebang line if present, otherwise at the
 * very start of the file. This preserves executable semantics while adding
 * only comment text.
 *
 * @supports docs/stories/021.0-DEV-TEST-ANNOTATION-AUTO-FIX.story.md REQ-TEST-FIX-TEMPLATE REQ-TEST-FIX-SAFE REQ-TEST-FIX-PRESERVE REQ-TEST-FIX-NO-INFERENCE
 */
function insertSupportsTemplate(
  fixer: any,
  sourceCode: any,
  customTemplate?: string,
) {
  const text: string = sourceCode.text || "";
  let insertIndex = 0;

  // Preserve shebang: it must remain the very first characters in the file.
  if (text.startsWith("#!")) {
    const firstNewline = text.indexOf("\n");
    insertIndex = firstNewline === NOT_FOUND ? text.length : firstNewline + 1;
  }

  const templateComment = buildSupportsTemplateComment(customTemplate);
  return fixer.insertTextBeforeRange(
    [insertIndex, insertIndex],
    templateComment,
  );
}

/**
 * Ensure the file has a @supports annotation listing tested requirements.
 *
 * When auto-fix is enabled, a placeholder @supports JSDoc is inserted at the
 * top of the file (after any shebang) using a safe, non-semantic template.
 *
 * @supports docs/stories/020.0-DEV-TEST-ANNOTATION-VALIDATION.story.md REQ-TEST-FILE-SUPPORTS REQ-TEST-SUPPORTS-VALID
 * @supports docs/stories/021.0-DEV-TEST-ANNOTATION-AUTO-FIX.story.md REQ-TEST-FIX-TEMPLATE REQ-TEST-FIX-PLACEHOLDER REQ-TEST-FIX-SAFE REQ-TEST-FIX-PRESERVE REQ-TEST-FIX-NO-INFERENCE
 */
export function ensureFileSupportsAnnotation(
  context: any,
  sourceCode: any,
  autoFixOptions: TestTraceabilityAutoFixOptions,
): void {
  const fileComments = sourceCode.getAllComments() || [];

  const fileHasSupports = fileComments.some((comment: any) =>
    /@supports\b/.test(comment.value || ""),
  );

  if (!fileHasSupports) {
    const node =
      (fileComments[0] as any) || (sourceCode.ast && (sourceCode.ast as any));

    context.report({
      node: node as any,
      messageId: "missingFileSupports",
      fix:
        autoFixOptions.autoFixTestTemplate === false
          ? undefined
          : (fixer: any) =>
              insertSupportsTemplate(
                fixer,
                sourceCode,
                autoFixOptions.testSupportsTemplate,
              ),
    });
  }
}

/**
 * Check if a callee name corresponds to a test framework function.
 *
 * @supports docs/stories/020.0-DEV-TEST-ANNOTATION-VALIDATION.story.md REQ-TEST-FRAMEWORK-COMPAT
 */
function isTestCallName(name: string): boolean {
  return ["describe", "it", "test", "context"].includes(name);
}

function getCalleeName(node: any): string | null {
  if (node.callee.type === "Identifier") {
    return node.callee.name;
  }
  if (
    node.callee.type === "MemberExpression" &&
    node.callee.object.type === "Identifier"
  ) {
    return node.callee.object.name;
  }
  return null;
}

function getFirstArgumentLiteral(node: any): string | null {
  const arg = node.arguments && node.arguments[0];
  if (!arg) return null;
  if (arg.type === "Literal" && typeof arg.value === "string") {
    return arg.value;
  }
  return null;
}

/**
 * Normalize a raw REQ identifier string to canonical REQ-XXX format.
 *
 * This helper performs only local, format-level normalization without
 * inferring new requirement IDs.
 *
 * @supports docs/stories/021.0-DEV-TEST-ANNOTATION-AUTO-FIX.story.md REQ-TEST-FIX-PREFIX-FORMAT REQ-TEST-FIX-NO-INFERENCE
 */
function normalizeReqId(raw: string): string {
  let id = raw.trim().toUpperCase();

  if (!id.startsWith("REQ")) {
    return id;
  }

  let rest = id.slice(REQ_PREFIX_LENGTH);

  // Drop leading separators after "REQ"
  rest = rest.replace(/^[-_\s:]+/, "");
  // Convert internal whitespace/underscores to hyphens
  rest = rest.replace(/[\s_]+/g, "-");
  // Collapse multiple hyphens
  rest = rest.replace(/-+/g, "-");

  return rest ? `REQ-${rest}` : "REQ-";
}

/**
 * Normalize malformed [REQ-XXX] prefixes in test names.
 *
 * Handles cases such as:
 * - "[ REQ-XXX ] ..."  -> "[REQ-XXX] ..."
 * - "[REQ_XXX] ..."    -> "[REQ-XXX] ..."
 * - "(REQ-XXX) ..."    -> "[REQ-XXX] ..."
 * - "[req-xxx] ..."    -> "[REQ-XXX] ..."
 *
 * Only operates when a REQ identifier is already present at the start of the
 * string; it never invents new IDs.
 *
 * @supports docs/stories/021.0-DEV-TEST-ANNOTATION-AUTO-FIX.story.md REQ-TEST-FIX-PREFIX-FORMAT REQ-TEST-FIX-SAFE REQ-TEST-FIX-PRESERVE REQ-TEST-FIX-NO-INFERENCE
 */
function normalizeReqPrefixInDescription(description: string): string | null {
  const canonicalPattern = /^\[REQ-[^\]]+]/;
  if (canonicalPattern.test(description)) {
    return null;
  }

  // Leading square brackets with optional spacing.
  const squareMatch = description.match(/^\[\s*(REQ[^\]]*?)\s*](.*)$/i);
  if (squareMatch) {
    const normalizedId = normalizeReqId(squareMatch[1]);
    return `[${normalizedId}]${squareMatch[2] ?? ""}`;
  }

  // Leading parentheses with optional spacing.
  const parenMatch = description.match(/^\(\s*(REQ[^)]*?)\s*\)(.*)$/i);
  if (parenMatch) {
    const normalizedId = normalizeReqId(parenMatch[1]);
    return `[${normalizedId}]${parenMatch[2] ?? ""}`;
  }

  return null;
}

/**
 * Create a string literal with the same quote style as the original node.
 *
 * This helper rewrites only the literal value while preserving the original
 * quoting character (`'`, `"`, or `` ` ``) and escaping rules.
 *
 * @supports docs/stories/021.0-DEV-TEST-ANNOTATION-AUTO-FIX.story.md REQ-TEST-FIX-PRESERVE
 */
function createUpdatedStringLiteralRaw(
  originalNode: any,
  newValue: string,
  sourceCode: any,
): string {
  const raw = sourceCode.getText(originalNode);
  const firstChar = raw[0];

  if (QUOTES.includes(firstChar as (typeof QUOTES)[number])) {
    const quote = firstChar;
    const escaped = newValue
      .replace(/\\/g, "\\\\")
      .replace(new RegExp(`\\${quote}`, "g"), `\\${quote}`);
    return `${quote}${escaped}${quote}`;
  }

  // Fallback: let JSON.stringify choose a safe representation.
  return JSON.stringify(newValue);
}

function handleDescribeCall(
  context: any,
  node: any,
  description: string,
  options: { describeRegex: RegExp; requireDescribeStory: boolean },
): void {
  const { describeRegex, requireDescribeStory } = options;
  if (!requireDescribeStory) return;
  if (!describeRegex.test(description)) {
    context.report({
      node: node as any,
      messageId: "missingDescribeStory",
    });
  }
}

function handleItOrTestCall(
  context: any,
  node: any,
  description: string,
  options: CallExpressionOptions,
): void {
  const { sourceCode, requireTestReqPrefix, autoFixTestPrefixFormat } = options;

  if (!requireTestReqPrefix) return;

  if (!/^\[REQ-[^\]]+]/.test(description)) {
    const normalizedDescription =
      autoFixTestPrefixFormat !== false
        ? normalizeReqPrefixInDescription(description)
        : null;

    context.report({
      node: node as any,
      messageId: "missingReqPrefix",
      ...(autoFixTestPrefixFormat !== false &&
      normalizedDescription !== null &&
      node.arguments &&
      node.arguments[0] &&
      node.arguments[0].type === "Literal" &&
      typeof node.arguments[0].value === "string"
        ? {
            fix(fixer: any) {
              const literalNode = node.arguments[0];
              const newRaw = createUpdatedStringLiteralRaw(
                literalNode,
                normalizedDescription,
                sourceCode,
              );
              return fixer.replaceText(literalNode, newRaw);
            },
          }
        : {}),
    });
  }
}

/**
 * Build a CallExpression visitor for the main rule create() function.
 *
 * @supports docs/stories/020.0-DEV-TEST-ANNOTATION-VALIDATION.story.md REQ-TEST-DESCRIBE-STORY REQ-TEST-IT-REQ-PREFIX REQ-TEST-NESTED-DESCRIBE REQ-TEST-ERROR-CONTEXT
 * @supports docs/stories/021.0-DEV-TEST-ANNOTATION-AUTO-FIX.story.md REQ-TEST-FIX-PREFIX-FORMAT REQ-TEST-FIX-SAFE REQ-TEST-FIX-PRESERVE REQ-TEST-FIX-NO-INFERENCE
 */
export function handleCallExpression(
  context: any,
  options: CallExpressionOptions,
) {
  const { describeRegex, requireDescribeStory } = options;

  return (node: any) => {
    const calleeName = getCalleeName(node);
    if (!calleeName || !isTestCallName(calleeName)) {
      return;
    }

    const description = getFirstArgumentLiteral(node);
    if (!description) return;

    if (calleeName === "describe") {
      handleDescribeCall(context, node, description, {
        describeRegex,
        requireDescribeStory,
      });
      return;
    }

    if (calleeName === "it" || calleeName === "test") {
      handleItOrTestCall(context, node, description, options);
    }
  };
}

/**
 * Internal helpers and types for the valid-annotation-format rule.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-MULTILINE-SUPPORT - Handle annotations split across multiple lines
 * @req REQ-FLEXIBLE-PARSING - Support reasonable variations in whitespace and formatting
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 * @req REQ-SUPPORTS-PARSE - Parse @supports annotations without affecting @story/@req
 * @req REQ-MIXED-SUPPORT - Support mixed @story/@req/@implements usage in comments
 */

/**
 * Pending annotation state tracked while iterating through comment lines.
 */
export interface PendingAnnotation {
  type: "story" | "req";
  value: string;
  hasValue: boolean;
}

/**
 * Normalize a raw comment line to make annotation parsing more robust.
 *
 * This function trims whitespace, keeps any annotation tags that appear
 * later in the line, and supports common JSDoc styles such as leading "*".
 *
 * It detects @story, @req, and @supports tags while preserving the rest
 * of the line for downstream logic.
 */
export function normalizeCommentLine(rawLine: string): string {
  const trimmed = rawLine.trim();
  if (!trimmed) {
    return "";
  }

  const annotationMatch = trimmed.match(/@story\b|@req\b|@supports\b/);
  if (!annotationMatch || annotationMatch.index === undefined) {
    const withoutLeadingStar = trimmed.replace(/^\*\s?/, "");
    return withoutLeadingStar;
  }

  return trimmed.slice(annotationMatch.index);
}

/**
 * Detect whether a normalized comment line starts with a non-traceability JSDoc tag.
 *
 * This is used to distinguish regular JSDoc tags (e.g. @param, @returns) from
 * traceability-related annotations such as @story, @req, and @supports.
 *
 * @supports docs/stories/022.0-DEV-JSDOC-COEXISTENCE.story.md
 * @req REQ-JSDOC-BOUNDARY-DETECTION
 * @req REQ-JSDOC-TAG-COEXISTENCE
 */
export function isNonTraceabilityJSDocTagLine(normalized: string): boolean {
  const trimmed = normalized.trimStart();
  if (!trimmed || !trimmed.startsWith("@")) {
    return false;
  }

  if (/^@(story|req|supports)\b/.test(trimmed)) {
    return false;
  }

  return true;
}

/**
 * Validators and helper functions for the valid-annotation-format rule.
 *
 * This module contains the core validation logic that was originally
 * embedded in src/rules/valid-annotation-format.ts. It is extracted
 * here to keep the main rule module smaller and easier to read while
 * preserving existing behavior.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/007.0-DEV-ERROR-REPORTING.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.1-DEV-CONFIGURABLE-PATTERNS.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-FORMAT-SPECIFICATION
 * @req REQ-SYNTAX-VALIDATION
 * @req REQ-PATH-FORMAT
 * @req REQ-REQ-FORMAT
 * @req REQ-MULTILINE-SUPPORT
 * @req REQ-AUTOFIX-FORMAT
 * @req REQ-ERROR-SPECIFICITY
 * @req REQ-REGEX-VALIDATION
 * @req REQ-BACKWARD-COMP
 * @req REQ-SUPPORTS-PARSE
 * @req REQ-FORMAT-VALIDATION
 * @req REQ-MIXED-SUPPORT
 */

import type { ResolvedAnnotationOptions } from "./valid-annotation-options";
import {
  collapseAnnotationValue,
  TAG_NOT_FOUND_INDEX,
  getFixedStoryPath,
  buildStoryErrorMessage,
  buildReqErrorMessage,
} from "./valid-annotation-utils";
import {
  MIN_IMPLEMENTS_TOKENS,
  reportMissingImplementsReqIds,
  reportMissingImplementsValue,
  reportInvalidImplementsReqId,
  reportInvalidImplementsStoryPath,
  validateImplementsAnnotationHelper,
} from "./valid-implements-utils";
import type { PendingAnnotation } from "./valid-annotation-format-internal";
import { getResolvedDefaults } from "./valid-annotation-options";

/**
 * Report an invalid @story annotation without applying a fix.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 */
export function reportInvalidStoryFormat(
  context: any,
  comment: any,
  collapsed: string,
  options: ResolvedAnnotationOptions,
): void {
  context.report({
    node: comment as any,
    messageId: "invalidStoryFormat",
    data: { details: buildStoryErrorMessage("invalid", collapsed, options) },
  });
}

/**
 * Compute the text replacement for an invalid @story annotation within a comment.
 *
 * This helper:
 *   - finds the @story tag in the raw comment text,
 *   - computes the character range of its value,
 *   - and returns an ESLint fix that replaces only that range.
 *
 * Returns null when the tag or value cannot be safely located.
 *
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @req REQ-AUTOFIX-SAFE
 * @req REQ-AUTOFIX-PRESERVE
 */
export function createStoryFix(
  context: any,
  comment: any,
  fixed: string,
): null | (() => any) {
  const sourceCode = context.getSourceCode();
  const commentText = sourceCode.getText(comment);
  const search = "@story";
  const tagIndex = commentText.indexOf(search);
  // @story docs/stories/008.0-DEV-AUTO-FIX.story.md
  // @req REQ-AUTOFIX-SAFE - Skip auto-fix when @story tag cannot be reliably located
  if (tagIndex === TAG_NOT_FOUND_INDEX) {
    return null;
  }

  const afterTagIndex = tagIndex + search.length;
  const rest = commentText.slice(afterTagIndex);
  const valueMatch = rest.match(/[^\S\r\n]*([^\r\n*]+)/);
  // @story docs/stories/008.0-DEV-AUTO-FIX.story.md
  // @req REQ-AUTOFIX-SAFE - Abort auto-fix when story value range cannot be safely determined
  if (!valueMatch || valueMatch.index === undefined) {
    return null;
  }

  const valueStartInComment =
    afterTagIndex +
    valueMatch.index +
    (valueMatch[0].length - valueMatch[1].length);
  const valueEndInComment = valueStartInComment + valueMatch[1].length;

  const start = comment.range[0];
  const fixRange: [number, number] = [
    start + valueStartInComment,
    start + valueEndInComment,
  ];

  return () => (fixer: any) => fixer.replaceTextRange(fixRange, fixed);
}

/**
 * Report an invalid @story annotation and attempt a minimal, safe auto-fix
 * for common path suffix issues by locating and replacing the path text
 * within the original comment.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-PATH-FORMAT - Validate @story paths follow expected patterns
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 * @req REQ-AUTOFIX-SAFE - Auto-fix must be conservative and avoid changing semantics
 * @req REQ-AUTOFIX-PRESERVE - Auto-fix must preserve surrounding formatting and comments
 */
export function reportInvalidStoryFormatWithFix(
  context: any,
  comment: any,
  collapsed: string,
  fixed: string,
): void {
  const fixFactory = createStoryFix(context, comment, fixed);
  // @story docs/stories/008.0-DEV-AUTO-FIX.story.md
  // @req REQ-AUTOFIX-SAFE - Fall back to reporting without fix when safe fix cannot be created
  if (!fixFactory) {
    reportInvalidStoryFormat(
      context,
      comment,
      collapsed,
      getResolvedDefaults(),
    );
    return;
  }

  context.report({
    node: comment as any,
    messageId: "invalidStoryFormat",
    data: {
      details: buildStoryErrorMessage(
        "invalid",
        collapsed,
        getResolvedDefaults(),
      ),
    },
    fix: fixFactory(),
  });
}

/**
 * Validate a @story annotation value and report detailed errors when needed.
 * Where safe and unambiguous, apply an automatic fix for missing suffixes.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-PATH-FORMAT - Validate @story paths follow expected patterns
 * @req REQ-ERROR-SPECIFICITY - Provide specific error messages for different format violations
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 * @req REQ-REGEX-VALIDATION - Validate configurable story regex patterns and fall back safely
 * @req REQ-BACKWARD-COMP - Preserve behavior when invalid regex config is supplied
 * @req REQ-MIXED-SUPPORT - Support mixed @story/@req/@implements usage in comments
 */
export function validateStoryAnnotation(
  context: any,
  comment: any,
  rawValue: string,
  options: ResolvedAnnotationOptions,
): void {
  const trimmed = rawValue.trim();
  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
  // @req REQ-PATH-FORMAT - Treat missing @story value as a specific validation error
  if (!trimmed) {
    context.report({
      node: comment as any,
      messageId: "invalidStoryFormat",
      data: { details: buildStoryErrorMessage("missing", null, options) },
    });
    return;
  }

  const collapsed = collapseAnnotationValue(trimmed);
  const pathPattern = options.storyPattern;

  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
  // @req REQ-PATH-FORMAT - Accept @story value when it matches configured storyPattern
  if (pathPattern.test(collapsed)) {
    return;
  }

  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
  // @req REQ-PATH-FORMAT - Reject @story values containing internal whitespace as invalid
  if (/\s/.test(trimmed)) {
    reportInvalidStoryFormat(context, comment, collapsed, options);
    return;
  }

  const fixed = getFixedStoryPath(collapsed);

  // @story docs/stories/008.0-DEV-AUTO-FIX.story.md
  // @req REQ-AUTOFIX-FORMAT - Apply suffix-only auto-fix when it yields a pattern-compliant path
  if (fixed && pathPattern.test(fixed)) {
    if (options.autoFix !== false) {
      reportInvalidStoryFormatWithFix(context, comment, collapsed, fixed);
      return;
    }

    reportInvalidStoryFormat(context, comment, collapsed, options);
    return;
  }

  reportInvalidStoryFormat(context, comment, collapsed, options);
}

/**
 * Validate a @req annotation value and report detailed errors when needed.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-REQ-FORMAT - Validate @req identifiers follow expected patterns
 * @req REQ-ERROR-SPECIFICITY - Provide specific error messages for different format violations
 * @req REQ-REGEX-VALIDATION - Validate configurable requirement regex patterns and fall back safely
 * @req REQ-BACKWARD-COMP - Preserve behavior when invalid regex config is supplied
 * @req REQ-MIXED-SUPPORT - Support mixed @story/@req/@implements usage in comments
 */
export function validateReqAnnotation(
  context: any,
  comment: any,
  rawValue: string,
  options: ResolvedAnnotationOptions,
): void {
  const trimmed = rawValue.trim();
  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
  // @req REQ-REQ-FORMAT - Treat missing @req value as a specific validation error
  if (!trimmed) {
    context.report({
      node: comment as any,
      messageId: "invalidReqFormat",
      data: { details: buildReqErrorMessage("missing", null, options) },
    });
    return;
  }

  const collapsed = collapseAnnotationValue(trimmed);
  const reqPattern = options.reqPattern;

  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
  // @req REQ-REQ-FORMAT - Flag @req identifiers that do not match the configured pattern
  if (!reqPattern.test(collapsed)) {
    context.report({
      node: comment as any,
      messageId: "invalidReqFormat",
      data: { details: buildReqErrorMessage("invalid", collapsed, options) },
    });
  }
}

/**
 * Validate an @supports annotation value and report detailed errors when needed.
 *
 * Expected format:
 *   @supports <storyPath> <REQ-ID> [<REQ-ID> ...]
 *
 * Validation rules:
 *   - Value must include at least a story path and one requirement ID.
 *   - Story path must match the same storyPattern used for @story (no auto-fix).
 *   - Each subsequent token must match reqPattern and is validated individually.
 *
 * Story path issues are reported with "invalidImplementsFormat" and
 * requirement ID issues reuse the existing "invalidReqFormat" message.
 *
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-SUPPORTS-PARSE - Parse @supports annotations without affecting @story/@req
 * @req REQ-FORMAT-VALIDATION - Validate @implements story path and requirement IDs
 * @req REQ-MIXED-SUPPORT - Support mixed @story/@req/@implements usage in comments
 */
export function validateImplementsAnnotation(
  context: any,
  comment: any,
  rawValue: string,
  options: ResolvedAnnotationOptions,
): void {
  const deps = {
    MIN_IMPLEMENTS_TOKENS,
    reportMissingImplementsReqIds,
    reportMissingImplementsValue,
    reportInvalidImplementsReqId,
    reportInvalidImplementsStoryPath,
  };

  validateImplementsAnnotationHelper(deps, context, comment, {
    rawValue,
    options,
  });
}

/**
 * Finalize and validate the currently pending annotation, if any.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-SYNTAX-VALIDATION - Validate annotation syntax matches specification
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 * @req REQ-MIXED-SUPPORT - Support mixed @story/@req/@implements usage in comments
 */
export function finalizePendingAnnotation(
  context: any,
  comment: any,
  options: ResolvedAnnotationOptions,
  pending: PendingAnnotation | null,
): PendingAnnotation | null {
  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
  // @req REQ-MULTILINE-SUPPORT - Do nothing when there is no pending multi-line annotation to finalize
  if (!pending) {
    return null;
  }

  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
  // @req REQ-SYNTAX-VALIDATION - Dispatch to @story or @req validator based on pending annotation type
  // @req REQ-AUTOFIX-FORMAT - Route to story validator which may apply safe auto-fixes
  // @req REQ-MIXED-SUPPORT - Ensure @story and @req annotations are handled independently
  if (pending.type === "story") {
    validateStoryAnnotation(context, comment, pending.value, options);
  } else {
    validateReqAnnotation(context, comment, pending.value, options);
  }

  return null;
}

/**
 * Shared option handling for the valid-annotation-format rule.
 *
 * @story docs/stories/010.1-DEV-CONFIGURABLE-PATTERNS.story.md
 * @req REQ-PATTERN-CONFIG - Support configuration of custom story path and requirement ID patterns
 * @req REQ-REGEX-VALIDATION - Validate that configured patterns are valid regular expressions
 * @req REQ-BACKWARD-COMPAT - Maintain current behavior when no custom patterns configured
 * @req REQ-EXAMPLE-MESSAGES - Support optional example strings in error messages
 * @req REQ-SCHEMA-VALIDATION - Use JSON Schema to validate configuration options
 */
export interface AnnotationRuleOptions {
  story?: {
    /**
     * Regex (string) the collapsed story path must match.
     * Default: /^docs\/stories\/[0-9]+\.[0-9]+-DEV-[\w-]+\.story\.md$/
     */
    pattern?: string;
    /**
     * Human-readable example path used in error messages.
     * Default: "docs/stories/005.0-DEV-EXAMPLE.story.md"
     */
    example?: string;
  };
  req?: {
    /**
     * Regex (string) the collapsed requirement ID must match.
     * Default: /^REQ-[A-Z0-9-]+$/
     */
    pattern?: string;
    /**
     * Human-readable example requirement ID used in error messages.
     * Default: "REQ-EXAMPLE"
     */
    example?: string;
  };

  /**
   * Shorthand for story.pattern.
   * Regex (string) the collapsed story path must match.
   */
  storyPathPattern?: string;
  /**
   * Shorthand for story.example.
   * Human-readable example story path used in error messages.
   */
  storyPathExample?: string;

  /**
   * Shorthand for req.pattern.
   * Regex (string) the collapsed requirement ID must match.
   */
  requirementIdPattern?: string;
  /**
   * Shorthand for req.example.
   * Human-readable example requirement ID used in error messages.
   */
  requirementIdExample?: string;

  /**
   * Global toggle for auto-fix behavior in valid-annotation-format.
   * When false, no automatic suffix-normalization fixes are applied.
   */
  autoFix?: boolean;
}

/**
 * Resolved, runtime-ready options for the rule.
 */
export interface ResolvedAnnotationOptions {
  storyPattern: RegExp;
  storyExample: string;
  reqPattern: RegExp;
  reqExample: string;
  autoFix: boolean;
}

function getDefaultStoryPattern(): RegExp {
  return /^docs\/stories\/[0-9]+\.[0-9]+-DEV-[\w-]+\.story\.md$/;
}

function getDefaultStoryExample(): string {
  return "docs/stories/005.0-DEV-EXAMPLE.story.md";
}

function getDefaultReqPattern(): RegExp {
  return /^REQ-[A-Z0-9-]+$/;
}

export function getDefaultReqExample(): string {
  return "REQ-EXAMPLE";
}

/**
 * Global cache of the last resolved options for helpers that need access
 * without having options explicitly passed in.
 */
let resolvedDefaults: ResolvedAnnotationOptions = {
  storyPattern: getDefaultStoryPattern(),
  storyExample: getDefaultStoryExample(),
  reqPattern: getDefaultReqPattern(),
  reqExample: getDefaultReqExample(),
  autoFix: true,
};

/**
 * Collected configuration errors encountered while resolving options.
 */
let optionErrors: string[] = [];

export function getResolvedDefaults(): ResolvedAnnotationOptions {
  return resolvedDefaults;
}

export function getOptionErrors(): string[] {
  return optionErrors;
}

/**
 * Build a stable, engine-independent configuration error message
 * for invalid regex options.
 */
function buildInvalidRegexError(field: string, pattern: string): string {
  return `Invalid regular expression for option "${field}": "${pattern}"`;
}

/**
 * Normalize raw rule options into a single AnnotationRuleOptions object.
 *
 * @story docs/stories/010.1-DEV-CONFIGURABLE-PATTERNS.story.md
 * @req REQ-PATTERN-CONFIG
 * @req REQ-BACKWARD-COMPAT
 */
function normalizeUserOptions(
  rawOptions: unknown[],
): AnnotationRuleOptions | undefined {
  if (!rawOptions || rawOptions.length === 0) {
    return undefined;
  }

  const first = rawOptions[0];
  if (!first || typeof first !== "object") {
    return undefined;
  }

  return first as AnnotationRuleOptions;
}

interface ResolvePatternArgs {
  nestedPattern: string | undefined;
  nestedFieldName: string;
  flatPattern: string | undefined;
  flatFieldName: string;
  defaultPattern: RegExp;
}

/**
 * Resolve a user-configured regex pattern, handling both nested and flat
 * configuration shapes and accumulating validation errors.
 *
 * @story docs/stories/010.1-DEV-CONFIGURABLE-PATTERNS.story.md
 * @req REQ-PATTERN-CONFIG
 * @req REQ-REGEX-VALIDATION
 * @req REQ-BACKWARD-COMPAT
 */
function resolvePattern({
  nestedPattern,
  nestedFieldName,
  flatPattern,
  flatFieldName,
  defaultPattern,
}: ResolvePatternArgs): RegExp {
  const effective =
    typeof nestedPattern === "string"
      ? { value: nestedPattern, field: nestedFieldName }
      : typeof flatPattern === "string"
        ? { value: flatPattern, field: flatFieldName }
        : null;

  if (!effective) {
    return defaultPattern;
  }

  try {
    return new RegExp(effective.value);
  } catch {
    optionErrors.push(buildInvalidRegexError(effective.field, effective.value));
    return defaultPattern;
  }
}

/**
 * Resolve an example string, preferring nested over flat configuration,
 * and falling back to the provided default when necessary.
 *
 * @story docs/stories/010.1-DEV-CONFIGURABLE-PATTERNS.story.md
 * @req REQ-EXAMPLE-MESSAGES
 * @req REQ-BACKWARD-COMPAT
 */
function resolveExample(
  nestedExample: string | undefined,
  flatExample: string | undefined,
  defaultExample: string,
): string {
  if (typeof nestedExample === "string" && nestedExample.trim()) {
    return nestedExample;
  }

  if (typeof flatExample === "string" && flatExample.trim()) {
    return flatExample;
  }

  return defaultExample;
}

function getUserOptions(
  rawOptions: unknown[],
): AnnotationRuleOptions | undefined {
  return normalizeUserOptions(rawOptions);
}

function resolveAutoFixFlag(user: AnnotationRuleOptions | undefined): boolean {
  const autoFixFlag = user?.autoFix;
  return typeof autoFixFlag === "boolean" ? autoFixFlag : true;
}

function resolveStoryPattern(
  nestedStoryPattern: string | undefined,
  flatStoryPattern: string | undefined,
): RegExp {
  return resolvePattern({
    nestedPattern: nestedStoryPattern,
    nestedFieldName: "story.pattern",
    flatPattern: flatStoryPattern,
    flatFieldName: "storyPathPattern",
    defaultPattern: getDefaultStoryPattern(),
  });
}

function resolveReqPattern(
  nestedReqPattern: string | undefined,
  flatReqPattern: string | undefined,
): RegExp {
  return resolvePattern({
    nestedPattern: nestedReqPattern,
    nestedFieldName: "req.pattern",
    flatPattern: flatReqPattern,
    flatFieldName: "requirementIdPattern",
    defaultPattern: getDefaultReqPattern(),
  });
}

function resolveStoryExample(
  nestedStoryExample: string | undefined,
  flatStoryExample: string | undefined,
): string {
  return resolveExample(
    nestedStoryExample,
    flatStoryExample,
    getDefaultStoryExample(),
  );
}

function resolveReqExample(
  nestedReqExample: string | undefined,
  flatReqExample: string | undefined,
): string {
  return resolveExample(
    nestedReqExample,
    flatReqExample,
    getDefaultReqExample(),
  );
}

function getStoryPatternInputs(user: AnnotationRuleOptions | undefined): {
  nestedStoryPattern: string | undefined;
  flatStoryPattern: string | undefined;
} {
  return {
    nestedStoryPattern: user?.story?.pattern,
    flatStoryPattern: user?.storyPathPattern,
  };
}

function getStoryExampleInputs(user: AnnotationRuleOptions | undefined): {
  nestedStoryExample: string | undefined;
  flatStoryExample: string | undefined;
} {
  return {
    nestedStoryExample: user?.story?.example,
    flatStoryExample: user?.storyPathExample,
  };
}

function getReqPatternInputs(user: AnnotationRuleOptions | undefined): {
  nestedReqPattern: string | undefined;
  flatReqPattern: string | undefined;
} {
  return {
    nestedReqPattern: user?.req?.pattern,
    flatReqPattern: user?.requirementIdPattern,
  };
}

function getReqExampleInputs(user: AnnotationRuleOptions | undefined): {
  nestedReqExample: string | undefined;
  flatReqExample: string | undefined;
} {
  return {
    nestedReqExample: user?.req?.example,
    flatReqExample: user?.requirementIdExample,
  };
}

function resolveOptionsInternal(
  user: AnnotationRuleOptions | undefined,
): ResolvedAnnotationOptions {
  const { nestedStoryPattern, flatStoryPattern } = getStoryPatternInputs(user);
  const { nestedStoryExample, flatStoryExample } = getStoryExampleInputs(user);
  const { nestedReqPattern, flatReqPattern } = getReqPatternInputs(user);
  const { nestedReqExample, flatReqExample } = getReqExampleInputs(user);

  const autoFix = resolveAutoFixFlag(user);

  const storyPattern = resolveStoryPattern(
    nestedStoryPattern,
    flatStoryPattern,
  );
  const reqPattern = resolveReqPattern(nestedReqPattern, flatReqPattern);
  const storyExample = resolveStoryExample(
    nestedStoryExample,
    flatStoryExample,
  );
  const reqExample = resolveReqExample(nestedReqExample, flatReqExample);

  return {
    storyPattern,
    storyExample,
    reqPattern,
    reqExample,
    autoFix,
  };
}

/**
 * Resolve user options into concrete, validated configuration.
 * Falls back to existing defaults when options are not provided or invalid.
 */
export function resolveOptions(
  rawOptions: unknown[],
): ResolvedAnnotationOptions {
  optionErrors = [];

  const user = getUserOptions(rawOptions);
  const resolved = resolveOptionsInternal(user);

  resolvedDefaults = resolved;
  return resolvedDefaults;
}

/**
 * Build the JSON schema for rule options.
 */
export function getRuleSchema() {
  return [
    {
      type: "object",
      properties: {
        story: {
          type: "object",
          properties: {
            pattern: { type: "string" },
            example: { type: "string" },
          },
          additionalProperties: false,
        },
        req: {
          type: "object",
          properties: {
            pattern: { type: "string" },
            example: { type: "string" },
          },
          additionalProperties: false,
        },
        storyPathPattern: { type: "string" },
        storyPathExample: { type: "string" },
        requirementIdPattern: { type: "string" },
        requirementIdExample: { type: "string" },
      },
      additionalProperties: false,
    },
  ];
}

import { getDefaultReqExample } from "./valid-annotation-options";
import type { ResolvedAnnotationOptions } from "./valid-annotation-options";

/**
 * Shared constants and helpers for annotation-format validation.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @req REQ-MULTILINE-SUPPORT - Handle annotations split across multiple lines
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 */

/**
 * Constant to represent the "tag not found" index when searching
 * for @story or @req within a comment.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 * @req REQ-AUTOFIX-PRESERVE - Avoid risky text replacements when the annotation tag cannot be located
 */
export const TAG_NOT_FOUND_INDEX = -1;

export const STORY_EXAMPLE_PATH = "docs/stories/005.0-DEV-EXAMPLE.story.md";

/**
 * Collapse internal whitespace in an annotation value so that multi-line
 * annotations are treated as a single logical value.
 *
 * Example:
 *   "docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md" across
 *   multiple lines will be collapsed before validation.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @req REQ-MULTILINE-SUPPORT - Handle annotations split across multiple lines
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 */
export function collapseAnnotationValue(value: string): string {
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-MULTILINE-SUPPORT
  return value.replace(/\s+/g, "");
}

/**
 * Attempt a minimal, safe auto-fix for common @story path suffix issues.
 *
 * Only handles:
 *   - missing ".md"
 *   - missing ".story.md"
 * and skips any paths with traversal segments (e.g. "..").
 *
 * Returns the fixed path when safe, or null if no fix should be applied.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md
 * @story docs/stories/010.2-REQ-STORY-PATH-AUTOFIX.story.md
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 * @req REQ-AUTOFIX-SAFE - Auto-fix must be conservative and never broaden the referenced path
 * @req REQ-AUTOFIX-PRESERVE - Preserve surrounding formatting when normalizing story path suffixes
 */
export function getFixedStoryPath(original: string): string | null {
  // @story docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md | REQ-AUTOFIX-SAFE - Reject auto-fix when the path contains ".." traversal segments to avoid broadening the reference.
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT REQ-ERROR-SPECIFICITY - Enforces correctness of the story identifier by rejecting paths that use unsafe traversal segments.
  if (original.includes("..")) {
    // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT
    // @supports docs/stories/008.0-DEV-AUTO-FIX.story.md REQ-AUTOFIX-SAFE
    // @supports docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md REQ-AUTOFIX-SAFE
    return null;
  }

  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md | REQ-AUTOFIX-FORMAT - Leave correctly formatted ".story.md" paths unchanged so diagnostics are not hidden by redundant fixes.
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT REQ-ERROR-SPECIFICITY - Enforces correctness of the story identifier by recognizing already valid ".story.md" paths without altering them.
  if (/\.story\.md$/.test(original)) {
    // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT
    // @supports docs/stories/008.0-DEV-AUTO-FIX.story.md REQ-AUTOFIX-FORMAT
    // @supports docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md REQ-AUTOFIX-FORMAT
    return null;
  }

  // @story docs/stories/008.0-DEV-AUTO-FIX.story.md | REQ-AUTOFIX-FORMAT REQ-AUTOFIX-PRESERVE - When ".story" is present but ".md" is missing, append only the extension without altering the base path.
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT REQ-ERROR-SPECIFICITY - Enforces correctness of the story identifier by completing a partially correct ".story" suffix to the canonical ".story.md".
  if (/\.story$/.test(original)) {
    // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT
    // @supports docs/stories/008.0-DEV-AUTO-FIX.story.md REQ-AUTOFIX-FORMAT REQ-AUTOFIX-PRESERVE
    // @supports docs/stories/010.2-REQ-STORY-PATH-AUTOFIX.story.md REQ-AUTOFIX-FORMAT
    return `${original}.md`;
  }

  // @story docs/stories/010.2-REQ-STORY-PATH-AUTOFIX.story.md | REQ-AUTOFIX-FORMAT REQ-AUTOFIX-PRESERVE - Normalize plain ".md" doc paths to ".story.md" while keeping the rest of the path intact.
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT REQ-ERROR-SPECIFICITY - Enforces correctness of the story identifier by transforming generic ".md" references into canonical ".story.md" story paths.
  if (/\.md$/.test(original)) {
    // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT
    // @supports docs/stories/008.0-DEV-AUTO-FIX.story.md REQ-AUTOFIX-FORMAT REQ-AUTOFIX-PRESERVE
    // @supports docs/stories/010.2-REQ-STORY-PATH-AUTOFIX.story.md REQ-AUTOFIX-FORMAT
    return original.replace(/\.md$/, ".story.md");
  }

  // @story docs/stories/010.2-REQ-STORY-PATH-AUTOFIX.story.md | REQ-AUTOFIX-FORMAT REQ-AUTOFIX-PRESERVE REQ-AUTOFIX-SAFE - For bare paths with no extension, append ".story.md" as a canonical story reference without touching the directory.
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT REQ-ERROR-SPECIFICITY - Enforces presence and correctness of the story identifier by supplying the standard ".story.md" suffix when no extension is provided.
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT
  // @supports docs/stories/008.0-DEV-AUTO-FIX.story.md REQ-AUTOFIX-FORMAT REQ-AUTOFIX-PRESERVE REQ-AUTOFIX-SAFE
  // @supports docs/stories/010.2-REQ-STORY-PATH-AUTOFIX.story.md REQ-AUTOFIX-FORMAT
  return `${original}.story.md`;
}

/**
 * Build a detailed error message for invalid @story annotations.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md
 * @req REQ-ERROR-SPECIFICITY - Provide specific error messages for different format violations
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 */
export function buildStoryErrorMessage(
  kind: "missing" | "invalid",
  value: string | null,
  options: ResolvedAnnotationOptions,
): string {
  const example = options.storyExample || STORY_EXAMPLE_PATH;

  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md | REQ-ERROR-SPECIFICITY - Use a dedicated message variant when the @story value is completely missing.
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT REQ-ERROR-SPECIFICITY - Enforces presence of the story identifier by emitting a targeted message when the @story value is absent.
  if (kind === "missing") {
    // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-ERROR-SPECIFICITY
    // @supports docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md REQ-ERROR-SPECIFICITY
    return `Missing story path for @story annotation. Expected a path like "${example}".`;
  }

  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-ERROR-SPECIFICITY
  // @supports docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md REQ-ERROR-SPECIFICITY
  return `Invalid story path "${value ?? ""}" for @story annotation. Expected a path like "${example}".`;
}

/**
 * Build a detailed error message for invalid @req annotations.
 *
 * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
 * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
 * @story docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md
 * @req REQ-ERROR-SPECIFICITY - Provide specific error messages for different format violations
 * @req REQ-AUTOFIX-FORMAT - Provide safe, minimal automatic fixes for common format issues
 */
export function buildReqErrorMessage(
  kind: "missing" | "invalid",
  value: string | null,
  options: ResolvedAnnotationOptions,
): string {
  const example = options.reqExample || getDefaultReqExample();

  // @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md | REQ-ERROR-SPECIFICITY - Distinguish a completely missing @req from one that is present but malformed.
  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-REQ-FORMAT REQ-ERROR-SPECIFICITY - Enforces presence of the requirement identifier by emitting a specific message when the @req value is missing.
  if (kind === "missing") {
    // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-ERROR-SPECIFICITY
    // @supports docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md REQ-ERROR-SPECIFICITY
    return `Missing requirement ID for @req annotation. Expected an identifier like "${example}".`;
  }

  // @supports docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md REQ-ERROR-SPECIFICITY
  // @supports docs/stories/010.1-REQ-STORY-PATH-STRICTNESS.story.md REQ-ERROR-SPECIFICITY
  return `Invalid requirement ID "${value ?? ""}" for @req annotation. Expected an identifier like "${example}" (uppercase letters, numbers, and dashes only).`;
}

/**
 * Helpers for @supports annotation validation used by valid-annotation-format.
 *
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-SUPPORTS-PARSE - Parse @supports annotations without affecting @story/@req
 * @req REQ-FORMAT-VALIDATION - Validate @supports story path and requirement IDs
 * @req REQ-MIXED-SUPPORT - Support mixed @story/@req/@supports usage in comments
 */
import type { ResolvedAnnotationOptions } from "./valid-annotation-options";
import { buildReqErrorMessage } from "./valid-annotation-utils";

/**
 * Minimum number of tokens required for a valid @supports value:
 *   - one story path
 *   - at least one requirement ID
 *
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-SUPPORTS-PARSE
 */
export const MIN_IMPLEMENTS_TOKENS = 2;

/**
 * Report a completely missing @supports value (no story path or req IDs).
 *
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-FORMAT-VALIDATION
 */
export function reportMissingImplementsValue(
  context: any,
  comment: any,
  options: ResolvedAnnotationOptions,
): void {
  const { storyExample, reqExample } = options;
  context.report({
    node: comment as any,
    messageId: "invalidImplementsFormat",
    data: {
      details: `Missing story path and requirement IDs for @supports annotation. Expected a value like "${storyExample} ${reqExample}".`,
    },
  });
}

/**
 * Report a value that has only a story path and no requirement IDs.
 *
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-FORMAT-VALIDATION
 */
export function reportMissingImplementsReqIds(
  context: any,
  comment: any,
  options: ResolvedAnnotationOptions,
): void {
  const { storyExample, reqExample } = options;
  context.report({
    node: comment as any,
    messageId: "invalidImplementsFormat",
    data: {
      details: `Missing requirement IDs for @supports annotation. Expected a value like "${storyExample} ${reqExample}".`,
    },
  });
}

/**
 * Report an invalid story path inside @supports.
 *
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-FORMAT-VALIDATION
 */
export function reportInvalidImplementsStoryPath(
  context: any,
  comment: any,
  storyPath: string,
  options: ResolvedAnnotationOptions,
): void {
  const { storyExample } = options;
  context.report({
    node: comment as any,
    messageId: "invalidImplementsFormat",
    data: {
      details: `Invalid story path "${storyPath}" for @supports annotation. Expected a path like "${storyExample}".`,
    },
  });
}

/**
 * Report an invalid requirement ID token inside @supports.
 *
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-FORMAT-VALIDATION
 * @req REQ-MIXED-SUPPORT
 */
export function reportInvalidImplementsReqId(
  context: any,
  comment: any,
  reqId: string,
  options: ResolvedAnnotationOptions,
): void {
  context.report({
    node: comment as any,
    messageId: "invalidReqFormat",
    data: {
      details: buildReqErrorMessage("invalid", reqId, options),
    },
  });
}

type ImplementsDeps = {
  MIN_IMPLEMENTS_TOKENS: number;
  reportMissingImplementsValue: typeof reportMissingImplementsValue;
  reportMissingImplementsReqIds: typeof reportMissingImplementsReqIds;
  reportInvalidImplementsStoryPath: typeof reportInvalidImplementsStoryPath;
  reportInvalidImplementsReqId: typeof reportInvalidImplementsReqId;
};

type ParsedImplementsTokens = {
  storyPath: string;
  reqIds: string[];
};

/**
 * Prepare and validate the token array for an @supports value.
 *
 * Returns { storyPath, reqIds } when tokens are present and structurally valid,
 * or null when a missing-value condition has been reported.
 */
function parseImplementsTokens(
  deps: ImplementsDeps,
  context: any,
  comment: any,
  rest: {
    rawValue: string | null | undefined;
    options: ResolvedAnnotationOptions;
  },
): ParsedImplementsTokens | null {
  const {
    MIN_IMPLEMENTS_TOKENS,
    reportMissingImplementsValue,
    reportMissingImplementsReqIds,
  } = deps;

  const { rawValue, options } = rest;
  const value = rawValue?.trim() ?? "";

  if (!value) {
    reportMissingImplementsValue(context, comment, options);
    return null;
  }

  const tokens = value.split(/\s+/);

  if (tokens.length < MIN_IMPLEMENTS_TOKENS) {
    reportMissingImplementsReqIds(context, comment, options);
    return null;
  }

  const [storyPath, ...reqIds] = tokens;
  return { storyPath, reqIds };
}

/**
 * Validate the parsed storyPath and reqIds against the provided patterns and
 * delegate reporting of any invalid tokens.
 */
function validateImplementsTokens(
  deps: ImplementsDeps,
  context: any,
  comment: any,
  rest: { parsed: ParsedImplementsTokens; options: ResolvedAnnotationOptions },
): void {
  const { reportInvalidImplementsStoryPath, reportInvalidImplementsReqId } =
    deps;
  const { parsed, options } = rest;
  const { storyPath, reqIds } = parsed;

  if (!options.storyPattern.test(storyPath)) {
    reportInvalidImplementsStoryPath(context, comment, storyPath, options);
    return;
  }

  for (const reqId of reqIds) {
    if (!options.reqPattern.test(reqId)) {
      reportInvalidImplementsReqId(context, comment, reqId, options);
    }
  }
}

/**
 * Validate an @supports annotation value.
 *
 * This helper encapsulates the logic previously in valid-annotation-format.ts:
 *   - trims the raw value
 *   - splits into tokens
 *   - enforces MIN_IMPLEMENTS_TOKENS
 *   - validates the story path using options.storyPattern
 *   - validates each requirement ID using options.reqPattern
 *   - delegates reporting to the provided helpers
 *
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-SUPPORTS-PARSE
 * @req REQ-FORMAT-VALIDATION
 * @req REQ-MIXED-SUPPORT
 */
export function validateImplementsAnnotationHelper(
  deps: ImplementsDeps,
  context: any,
  comment: any,
  args: {
    rawValue: string | null | undefined;
    options: ResolvedAnnotationOptions;
  },
): void {
  const { rawValue, options } = args;
  const parsed = parseImplementsTokens(deps, context, comment, {
    rawValue,
    options,
  });

  if (!parsed) {
    return;
  }

  validateImplementsTokens(deps, context, comment, { parsed, options });
}

import path from "path";
import { enforceProjectBoundary } from "../../utils/storyReferenceUtils";

/**
 * Helper utilities for valid-story-reference rule.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PROJECT-BOUNDARY - Ensure resolved candidate paths remain within the project root
 * @req REQ-SECURITY-VALIDATION - Prevent path traversal and absolute path usage
 */

export interface _ReportInvalidPathArgs {
  storyPath: string;
  commentNode: any;
  context: any;
}

export interface HandleBoundaryOptions {
  storyPath: string;
  commentNode: any;
  context: any;
  cwd: string;
  candidates: string[];
  existenceResult: {
    status: "exists" | "missing" | "fs-error" | null;
    matchedPath?: string | null;
  } | null;
  reportInvalidPath: (_args: _ReportInvalidPathArgs) => void;
}

export interface SecurityValidationOptions {
  storyPath: string;
  commentNode: any;
  context: any;
  cwd: string;
  allowAbsolute: boolean;
  reportInvalidPath: (_args: _ReportInvalidPathArgs) => void;
}

/**
 * Analyze candidate paths against the project boundary, returning whether any
 * are within the project and whether any are outside.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PROJECT-BOUNDARY - Validate files are within project boundaries
 * @req REQ-CONFIGURABLE-PATHS - Respect configured storyDirectories while enforcing project boundaries
 */
export function analyzeCandidateBoundaries(
  candidates: string[],
  cwd: string,
): {
  hasInProjectCandidate: boolean;
  hasOutOfProjectCandidate: boolean;
} {
  let hasInProjectCandidate = false;
  let hasOutOfProjectCandidate = false;

  for (const candidate of candidates) {
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
    const boundary = enforceProjectBoundary(candidate, cwd);
    if (boundary.isWithinProject) {
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY
      hasInProjectCandidate = true;
    } else {
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY
      hasOutOfProjectCandidate = true;
    }
  }

  return { hasInProjectCandidate, hasOutOfProjectCandidate };
}

/**
 * Determine whether any candidate or matched path crosses the project
 * boundary, and report an invalid path if so.
 *
 * This centralizes project-boundary invalidation logic used during
 * existence checks, so the decision of *when* to call the invalid-path
 * reporter is not duplicated.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PROJECT-BOUNDARY - Ensure resolved candidate paths remain within the project root
 * @req REQ-CONFIGURABLE-PATHS - Respect configured storyDirectories while enforcing project boundaries
 */
export function handleProjectBoundaryForExistence({
  storyPath,
  commentNode,
  context,
  cwd,
  candidates,
  existenceResult,
  reportInvalidPath,
}: HandleBoundaryOptions): boolean {
  if (candidates.length > 0) {
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
    const { hasInProjectCandidate, hasOutOfProjectCandidate } =
      analyzeCandidateBoundaries(candidates, cwd);

    if (hasOutOfProjectCandidate && !hasInProjectCandidate) {
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY
      reportInvalidPath({ storyPath, commentNode, context });
      return true;
    }
  }

  if (
    existenceResult &&
    existenceResult.status === "exists" &&
    existenceResult.matchedPath
  ) {
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY
    const boundary = enforceProjectBoundary(existenceResult.matchedPath, cwd);
    if (!boundary.isWithinProject) {
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY
      reportInvalidPath({ storyPath, commentNode, context });
      return true;
    }
  }

  return false;
}

/**
 * Perform security-related validations on the story path, including
 * absolute-path usage and path traversal checks. Report invalid paths
 * when necessary and indicate whether further processing should continue.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-SECURITY-VALIDATION - Prevent path traversal and absolute path usage
 */
export function performSecurityValidations({
  storyPath,
  commentNode,
  context,
  cwd,
  allowAbsolute,
  reportInvalidPath,
}: SecurityValidationOptions): boolean {
  // Absolute path check
  if (path.isAbsolute(storyPath)) {
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-SECURITY-VALIDATION
    if (!allowAbsolute) {
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-SECURITY-VALIDATION
      reportInvalidPath({ storyPath, commentNode, context });
      return false;
    }
    // When absolute paths are allowed, we still enforce extension and
    // project-boundary checks via the existence phase.
  }

  // Path traversal check
  const containsTraversal = storyPath.includes("..") || /\\|\//.test(storyPath);
  if (containsTraversal) {
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
    // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-SECURITY-VALIDATION
    const full = path.resolve(cwd, path.normalize(storyPath));
    if (!full.startsWith(cwd + path.sep)) {
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-PROJECT-BOUNDARY REQ-SECURITY-VALIDATION
      // @supports docs/stories/006.0-DEV-FILE-VALIDATION.story.md REQ-SECURITY-VALIDATION
      reportInvalidPath({ storyPath, commentNode, context });
      return false;
    }
  }

  return true;
}
